window.TADABBUR_QALAM = {"_meta":{"description":"تدبّر سورة القلم (٦٨)، وسورةٌ مكّيّةٌ، من أوائلِ ما نزل، تُسمّى سورةَ ن. محورُها الدفاعُ عن النبيِّ ﷺ وتبرئتُه من الجنون وإثباتُ خُلقِه العظيم، والنهيُ عن طاعةِ المكذّبين وذمُّ صفاتِ الأثيمِ الحلّاف، ومثلُ أصحابِ الجنّةِ الذين حُرِموا لبخلهم، وجزاءُ المتّقين، وإبطالُ دعاوى المجرمين، ومشهدُ يومِ يُكشَف عن ساق، والاستدراجُ، والأمرُ بالصبرِ وعدمِ العجلةِ كصاحبِ الحوت، وتقريرُ أنّ القرآنَ ذكرٌ للعالمين. فيها «وإنك لعلى خلق عظيم»، و«فلا تطع المكذبين»، و«فاصبر لحكم ربك ولا تكن كصاحب الحوت»، و«وما هو إلا ذكر للعالمين».","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":68,"name":"القلم","total_ayahs":52,"audio":[1,4,10,17,34,42,44,48,51,52],"passages":[{"title":"تبرئةُ النبيِّ وإثباتُ خُلقِه العظيم","range":[1,7],"theme":"القسمُ بالقلمِ وتنويهُ العلم، وتبرئةُ النبيِّ ﷺ من الجنون «ما أنت بنعمة ربك بمجنون» وبشارتُه بالأجرِ الدائم، و**«وإنك لعلى خلق عظيم»**، وأنّ العاقبةَ تكشف من هو المفتون، وأنّ الله «أعلم بمن ضل عن سبيله وهو أعلم بالمهتدين»","verses":[{"n":1,"reflection":{"text":"«ن والقلم وما يسطرون»: أقسم الله بالقلمِ وما يكتبون به تنويهًا بشأنِ العلمِ والكتابة؛ ففي هذا تعظيمُ شأنِ القلمِ والعلم؛ فعظّم العلمَ والكتابةَ واستعملهما في الخير، فالقلمُ أداةُ العلمِ والحفظ، فاستعمله في الحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ العلمِ والكتابة، واستعمالُ القلمِ في الخير."},"action":{"text":"تأمّل القسمَ بالقلم: ن (حرفٌ من الحروفِ المقطّعةِ للتنبيه)؛ والقلمِ، أي أقسم بالقلمِ الذي يُكتَب به (وأوّلُ ما خلق الله القلم)؛ وما يسطرون، أي وما يكتبه الكاتبون بالأقلام من العلومِ والكتب «ن والقلم وما يسطرون»؛ ففي هذا قسمٌ من الله بالقلمِ وما يُكتَب به، تنويهًا بشأنِ العلمِ والكتابةِ التي بها حفظُ العلوم؛ فالقلمُ نعمةٌ عظيمةٌ وأداةُ العلم؛ فعظّم أنت العلمَ والكتابة، واستعمل القلمَ في الخيرِ والحقِّ لا في الباطل؛ اقرأ وربّك الأكرم * الذي علّم بالقلم * علّم الإنسانَ ما لم يعلم؛ ن والقلمِ وما يسطرون؛ فالقلمُ أداةُ العلمِ والحفظِ والبيان؛ فاستعمله في تدوينِ العلمِ النافعِ ونصرةِ الحقّ، لا في الباطلِ والإثم؛ فمن استعمل قلمه في الحقِّ أُجِر، ومن استعمله في الباطلِ أثم؛ فاجعل تعظيمَ العلمِ والكتابةِ واستعمالَ القلمِ في الخيرِ دأبك."}},{"n":2,"reflection":{"text":"«ما أنت بنعمة ربك بمجنون»: ما أنت، يا محمد، بسببِ نعمةِ ربّك عليك بالنبوّةِ والعقلِ الكاملِ بمجنونٍ كما يزعم المكذّبون؛ ففي هذا تبرئةُ النبيِّ ﷺ من الجنون؛ فأيقن بكمالِ النبيِّ ﷺ وبراءته ممّا رماه به المكذّبون، فالنبيُّ ﷺ أكملُ الناسِ عقلًا، فأحبّه واتّبعه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ النبيِّ ﷺ ومحبّتُه واتّباعُه."},"action":{"text":"تأمّل تبرئةَ النبيِّ ﷺ: ما أنت، يا محمد، بنعمةِ ربّك (بسببِ إنعامه عليك بالنبوّةِ والرسالةِ والعقلِ الراجح) بمجنونٍ، كما يفتري عليك المكذّبون «ما أنت بنعمة ربك بمجنون»؛ ففي هذا تبرئةُ النبيِّ ﷺ ممّا رماه به المشركون من الجنون، وبيانُ أنّ ما هو عليه من كمالِ العقلِ والدينِ نعمةٌ من الله؛ فالنبيُّ ﷺ أكملُ الخلقِ عقلًا وأرجحُهم؛ فأيقن أنت بكمالِ النبيِّ ﷺ وبراءته من كلِّ نقص، وأحبّه واتّبعه؛ وما صاحبكم بمجنون؛ ما ضلّ صاحبكم وما غوى؛ ثم تتفكّروا ما بصاحبكم من جِنّة؛ فالنبيُّ ﷺ بريءٌ من الجنون، أكملُ الناسِ عقلًا وخُلقًا، بنعمةِ الله؛ فنزّهه، وأحبّه، واتّبع سنّته؛ فمن أحبّ النبيَّ واتّبعه أفلح، ومن طعن فيه خسر؛ فاجعل تنزيهَ النبيِّ ﷺ ومحبّتَه واتّباعَه دأبك."}},{"n":3,"reflection":{"text":"«وإن لك لأجرا غير ممنون»، وإنّ لك، يا محمد، لأجرًا عظيمًا غيرَ مقطوعٍ ولا منقوص؛ ففي هذا بشارةٌ للنبيِّ ﷺ بالأجرِ الدائم؛ فاعمل صالحًا محتسبًا لتنال الأجرَ الدائم، فالأجرُ غيرُ الممنونِ للمحسنين، فأحسِن واحتسب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ الصالحُ المحتسَب، وابتغاءُ الأجرِ الدائم."},"action":{"text":"تأمّل بشارةَ الأجرِ الدائم: وإنّ لك، يا محمد، لأجرًا غيرَ ممنونٍ، أي أجرًا عظيمًا دائمًا غيرَ مقطوعٍ ولا منقوص، على ما تحمّلته من أعباءِ الرسالةِ وصبرك على أذى المكذّبين «وإن لك لأجرا غير ممنون»؛ ففي هذا بشارةٌ للنبيِّ ﷺ بأجرٍ دائمٍ لا ينقطع، جزاءَ صبره وبلاغه وحسنِ خُلقه؛ فالأجرُ الدائمُ ثمرةُ العملِ الصالحِ والصبر؛ فاعمل أنت صالحًا محتسبًا، واصبر على أذى الحقّ، لتنال الأجرَ الدائمَ غيرَ الممنون؛ فلهم أجرٌ غيرُ ممنون؛ إنّ الذين آمنوا وعملوا الصالحاتِ لهم أجرٌ غيرُ ممنون؛ فالأجرُ غيرُ الممنونِ للمحسنين الصابرين؛ فأحسِن عملك، واحتسب الأجرَ عند الله، واصبر؛ فمن أحسن واحتسب نال الأجرَ الدائم، ومن أساء أو منّ حُرِم؛ فاجعل العملَ الصالحَ المحتسَبَ وابتغاءَ الأجرِ الدائمِ دأبك."}},{"n":4,"reflection":{"text":"«وإنك لعلى خلق عظيم»، وإنك، يا محمد، لعلى خُلقٍ عظيمٍ (وهو ما أدّبه الله به، جماعُ مكارمِ الأخلاق)؛ ففي هذا أعظمُ ثناءٍ على النبيِّ ﷺ بخُلقه؛ فاقتدِ بالنبيِّ ﷺ في خُلقه العظيمِ وتخلّق بمكارمِ الأخلاق، فالخلقُ العظيمُ من كمالِ الدين، فتخلّق به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بخُلقِ النبيِّ ﷺ، والتخلّقُ بمكارمِ الأخلاق."},"action":{"text":"تأمّل خُلقَ النبيِّ العظيم: وإنك، يا محمد، لعلى خُلقٍ عظيمٍ، أي على دينٍ عظيمٍ (الإسلام)، أو على جماعِ مكارمِ الأخلاقِ وأشرفها التي أدّبك الله بها، فكان خُلقه القرآن «وإنك لعلى خلق عظيم»؛ ففي هذا أعظمُ ثناءٍ على النبيِّ ﷺ، حيث شهد الله له بالخُلقِ العظيمِ الجامعِ لكلِّ فضيلة؛ فخُلقه العظيمُ قدوةٌ للناس؛ قالت عائشةُ: كان خُلقه القرآن؛ فاقتدِ أنت بالنبيِّ ﷺ في خُلقه العظيم، وتخلّق بمكارمِ الأخلاق (الحلمِ والصبرِ والكرمِ والعفوِ والرحمة)؛ لقد كان لكم في رسولِ الله أسوةٌ حسنة؛ إنما بُعِثتُ لأتمّم مكارمَ الأخلاق؛ فبما رحمةٍ من الله لنتَ لهم؛ فخُلقُ النبيِّ ﷺ العظيمُ جماعُ الفضائل، وهو قدوةٌ للمؤمنين؛ فاقتدِ به، وتخلّق بمكارمِ الأخلاق، وأحسِن معاملةَ الناس؛ فمن اقتدى بخُلقه أفلح، ومن ساء خُلقه خسر؛ فاجعل الاقتداءَ بخُلقِ النبيِّ ﷺ والتخلّقَ بمكارمِ الأخلاقِ دأبك."},"qadiyya":{"title":"قضيّةُ «خُلقٍ عظيم»: مدحةٌ لا يُنتفع بها، حتى سُئلت عائشةُ فأجابت بسؤال","question":"«وإنّك لعلى خُلقٍ عظيم» من أشهر ما يُقال في وصف النبيِّ ﷺ. تُتلى في الخطب، وتُكتب على الجدران.\nولكنّها بهذه الصورة **مدحةٌ لا يُنتفع بها**. فإنّ «الخلق العظيم» وصفٌ جميل، لكن ما هو؟ كيف يعرف الرجلُ أنّه اقترب منه أو بَعُد؟ وما الذي يفعله غدًا مختلفًا بعد أن سمعها؟\nوقد سُئلت أمُّ المؤمنين عائشةُ رضي الله عنها عن هذا بعينه، فجاء جوابُها على غير ما يُتوقّع: لم تصفه. **بل ردّت السؤالَ سؤالًا**.\nفالقضيّة: ما جوابُها؟ وكيف يحوّل مدحةً عامّةً إلى **شيءٍ يُقاس**؟","background":"ولا يُفهم موضعُ السؤال حتى نعرف أمرين:\nالأوّل: أنّ السورةَ نزلت جوابًا عن طعن. فقد رماه المشركون بالجنون، والآيةُ قبلها ﴿ما أنت بنعمة ربّك بمجنون﴾. فقولُه ﴿وإنّك لعلى خلقٍ عظيم﴾ **جاء في مقام الردّ، لا في مقام الثناء المجرّد**. والذي يُردّ به على تهمةٍ **يجب أن يكون معروفًا مشاهَدًا**، وإلّا لم يكن ردًّا.\nوالثاني: أنّ «الخُلق» في العربية هو **ما استقرّ في النفس فصدرت عنه الأفعالُ بلا تكلّف**، بخلاف «التخلّق» وهو التكلّف. فالسؤال عن خُلقه ﷺ سؤالٌ عن **طبعه الذي يعامل به الناسَ حين لا يُراقَب**.","what_happened":"أمّا الجوابُ فرواه ابنُ كثيرٍ بإسناده. سأل سعدُ بن هشامٍ عائشةَ رضي الله عنها عن خلق رسول الله ﷺ، فقالت: «أتقرأ القرآن؟» قال: نعم. فقالت: «كان خلقُه القرآن». وفي روايةٍ أخرى عنده: «ألستَ تقرأ القرآن؟ قال: بلى. قالت: فإنّ خلقَ رسول الله ﷺ كان القرآن». وقال ابنُ كثير: «وقد رواه الإمامُ مسلمٌ في صحيحه، من حديث قتادةَ بطوله».\nفتأمّلْ صنيعَها: جاءها رجلٌ يطلب وصفًا، فلم تعطه وصفًا؛ **أحالته على كتابٍ هو يقرؤه**. كأنّها تقول: الجوابُ في يدك منذ زمن.\nوأمّا السعديُّ فأخذ بجوابها وبنى عليه، فقال: «وحاصلُ خلقه العظيم، ما فسّرته به أمُّ المؤمنين»، **ثمّ عيّن من القرآن ما هو ذلك الخلق**، فذكر قولَه تعالى ﴿خذ العفوَ وأمرْ بالعرف وأعرضْ عن الجاهلين﴾، وقولَه ﴿فبما رحمةٍ من الله لنتَ لهم﴾، وقولَه ﴿لقد جاءكم رسولٌ من أنفسكم عزيزٌ عليه ما عنتّم حريصٌ عليكم بالمؤمنين رؤوفٌ رحيم﴾.\n**ثمّ نزل من الآيات إلى الأفعال**، فوصف عشرتَه ﷺ وصفًا يُرى:\n«فكان صلّى الله عليه وسلّم سهلًا ليّنًا، قريبًا من الناس، مجيبًا لدعوة من دعاه، قاضيًا لحاجة من استقضاه، جابرًا لقلب من سأله»، «لا يحرمه، ولا يردّه خائبًا».\nوفي الشورى: «وإن عزم على أمرٍ لم يستبدَّ به دونهم، بل يشاورهم ويؤامرهم».\nوفي احتمال الناس: «وكان يقبل من محسنهم، ويعفو عن مسيئهم».\nثمّ ذكر أشقَّ ما في الباب على النفوس، وهو **ما يقع بين الجليس وجليسه**: «فكان لا يعبس في وجهه، ولا يغلظ عليه في مقاله، ولا يطوي عنه بِشره، ولا يمسك عليه فلتاتِ لسانه»، «ولا يؤاخذه بما يصدر منه من جفوة».\nوأمّا معنى «الخلق العظيم» في نفسه فوقع فيه قولٌ آخر لم نكتمه: فقد نقل ابنُ كثيرٍ عن ابن عبّاسٍ أنّه «لعلى دينٍ عظيم، وهو الإسلام»، وقال: «وكذلك قال مجاهد، وأبو مالك، والسدّيّ، والربيع بن أنس، والضحّاك، وابن زيد». **فسبعةٌ من السلف على هذا**. وقال عطيّة: «لعلى أدبٍ عظيم».","the_verdict":"فالحاصلُ أنّ جوابَ عائشةَ رضي الله عنها **نقل الوصفَ من بابٍ إلى باب**.\nفـ«الخلق العظيم» لو بقي وصفًا مرسلًا لكان مدحةً تُقال ولا يُعمل بها. ولمّا قالت «كان خلقُه القرآن» **صار قائمةً محدّدة**: كلُّ أدبٍ أمر به القرآنُ فهو فيه ﷺ على أكمله. وصار الوصفُ قابلًا للفحص، إذ يستطيع القارئُ أن يفتح المصحفَ فيرى.\nوفي طريقة جوابها أدبٌ ثانٍ: **أنّها ردّت السائلَ إلى ما عنده**. فلم تُنشئ له علمًا جديدًا، بل نبّهته إلى أنّه يقرأ الوصفَ كلَّ يومٍ ولا يراه. وهذا داءٌ عامّ: أن يُطلب البعيدُ ويُهمل الحاضر.\n⭐ وأمّا الثمرةُ العمليّةُ فتظهر في تفصيل السعديّ، فإنّه لم يقتصر على وصفه بحسن الخلق ثمّ يسكت. بل عدَّ أفعالًا يمكن أن يُقاس عليها المرءُ نفسَه هذه الليلة: أيُجيب من دعاه؟ أيقضي حاجةَ من استقضاه؟ أيَعبس في وجه جليسه؟ أيُمسك عليه فلتاتِ لسانه؟\nوهذه الأخيرةُ أدقُّ ما في الباب. فإنّ فلتاتِ اللسان هي ما يقوله الجليسُ ولا يقصده: كلمةٌ في غير موضعها، أو جفوةٌ سبقته. وأكثرُ الخصومات بين الأقارب والأصحاب إنّما تُبنى على محفوظٍ من هذا الجنس. فالذي يُمسك على أخيه فلتاتِ لسانه **يجمع حجّةً ليومٍ يخاصمه فيه**؛ والنبيُّ ﷺ لم يكن يفعل.\nوأمّا الخلافُ في تفسير اللفظ فلا يضرّ عملًا. فمن قال «دينٌ عظيم» فقد جعل الخلقَ هو الدينَ نفسَه؛ ومن قال «أدبٌ عظيم» فقد أراد ما فسّرته عائشة. والقولان يلتقيان في أنّ الخُلق ليس شيئًا خارجًا عن الوحي؛ **إنّما هو الوحيُ مطبَّقًا في رجل**.","for_you":"فأمّا الذي تخرج به فثلاثة، وليس فيها شيءٌ يُؤجَّل:\nالأوّل: إذا أردتَ أن تعرف أين أنت من هذا الخلق، **فلا تسأل نفسَك سؤالًا عامًّا**. فإنّك إن سألتَ نفسَك: أحسنُ الخلقِ أنا؟ أجبتَ بنعم كما يجيب كلُّ أحد. بل خذ قائمةَ السعديِّ واسأل بندًا بندًا: مَن دعاني فلم أُجبه؟ ومَن استقضاني حاجةً فرددتُه؟ ومَن جلستُ إليه فعبستُ في وجهه؟ فالسؤالُ العامُّ يُجمِّل، **والسؤالُ المفصَّلُ يفضح**.\nوالثاني: أفرغْ ما جمعتَه من فلتات ألسنة الناس. فتّشْ عمّا تحفظه على أخيك أو زوجك أو زميلك ممّا قالوه في غضبٍ أو سهو. فإن وجدتَ نفسَك تُحصيه فاعلم **أنّك تُعدّ ملفًّا لخصومةٍ لم تقع بعد**. والنبيُّ ﷺ كان لا يمسكها، وهو أحقُّ الناس بأن يُحفظ له.\nوالثالث، وهو أدبُ عائشةَ لا مسألتُها: إذا سُئلتَ عن أمرٍ جوابُه بين يدي السائل، **فدُلَّه عليه ولا تُغنِه عنه**. «أتقرأ القرآن؟» أنفعُ من عشر صفحاتٍ يكتبها له؛ لأنّها تعلّمه أن ينظر بنفسه، وتلك عادةٌ تبقى بعد أن تُنسى الإجابة.","grade":"ma'thur","source":"جوابُ عائشةَ رضي الله عنها بروايتيه («فقالت: أتقرأ القرآن؟ فقلت: نعم. فقالت: كان خلقه القرآن»، و«فقالت: ألست تقرأ القرآن؟ قال: بلى. قالت: فإن خلق رسول الله ﷺ كان القرآن») وتخريجُ ابن كثير له («وقد رواه الإمام مسلم في صحيحه، من حديث قتادة بطوله»)، وقولُ ابن عبّاس («وإنك لعلى دين عظيم، وهو الإسلام») ومن وافقه («وكذلك قال مجاهد، وأبو مالك، والسدي، والربيع بن أنس، والضحاك، وابن زيد»)، وقولُ عطيّة («لعلى أدب عظيم»): كلُّها بنصّها في تفسير ابن كثير (٦٨:٤). وقولُ السعديّ «وحاصل خلقه العظيم، ما فسرته به أم المؤمنين»، ووصفُه «فكان صلى الله عليه وسلم سهلا لينا، قريبا من الناس، مجيبا لدعوة من دعاه، قاضيا لحاجة من استقضاه، جابرا لقلب من سأله»، و«وإن عزم على أمر لم يستبد به دونهم، بل يشاورهم ويؤامرهم»، و«وكان يقبل من محسنهم، ويعفو عن مسيئهم»، و«فكان لا يعبس في وجهه، ولا يغلظ عليه في مقاله، ولا يطوي عنه بشره، ولا يمسك عليه فلتات لسانه»، و«ولا يؤاخذه بما يصدر منه من جفوة»: كلُّها بنصّها في تفسير السعديّ (٦٨:٤). والآياتُ الثلاثُ التي عيّنها (الأعراف ١٩٩، وآل عمران ١٥٩، والتوبة ١٢٨) عُوضت على المصحف فطابقت.","honesty":"وممّا يجب أن يُقال:\nصحيحُ مسلمٍ ليس في كتب هذا المشروع، فنسبةُ حديث عائشةَ إليه نقلُ ابنِ كثيرٍ عنه، **والعهدةُ عليه في النسبة لا علينا**.\nولم نرجّح بين تفسير «الخلق العظيم» بالدين وتفسيرِه بالأدب، وقد نقل ابنُ كثيرٍ الأوّلَ عن سبعةٍ من السلف. وقولُنا إنّ القولين يلتقيان **لازمٌ استخرجناه، لا نصٌّ لإمام**؛ فمن رأى أنّا وسّعنا فليردّه.\nوأمّا قولُنا إنّ الآية جاءت في مقام الردّ على تهمة الجنون فمبنيٌّ على ترتيب الآيات في السورة، وقد ذكر ابنُ كثيرٍ معنى الردّ في هذا السياق.\nوأمّا تفسيرُ «الخُلق» بأنّه ما استقرّ في النفس فصدرت عنه الأفعالُ بلا تكلّف، فمعنًى لغويٌّ مشهور، ولم ننقله عن أحدٍ من الستّة في هذا الموضع بلفظه.\nوقائمةُ الأفعال التي دعونا القارئ أن يقيس نفسه بها مأخوذةٌ من وصف السعديّ بألفاظه؛ وصياغتُها أسئلةً من صنيعنا."}},{"n":5,"reflection":{"text":"«فستبصر ويبصرون»: فستُبصِر، يا محمد، ويُبصِرون أيّكم المفتونُ الضالّ؛ ففي هذا تهديدٌ للمكذّبين وتطمينٌ للنبيِّ ﷺ؛ فاصبر فإنّ العاقبةَ تكشف الحقَّ من الباطل، فالحقُّ يظهر والباطلُ يزهق، فاثبت على الحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الحقّ، واليقينُ بأنّ العاقبةَ تكشفه."},"action":{"text":"تأمّل كشفَ العاقبة: فستُبصِر، يا محمد، ويُبصِرون (المكذّبون) عمّا قريب؛ حين تظهر العاقبةُ ويتبيّن الحقُّ من الباطل «فستبصر ويبصرون»؛ ففي هذا تهديدٌ للمكذّبين وتطمينٌ للنبيِّ ﷺ، بأنّ العاقبةَ ستكشف من هو على الحقِّ ومن هو على الباطل؛ فالحقُّ يظهر والباطلُ يزهق؛ فاصبر أنت على الحقِّ، وأيقن بأنّ العاقبةَ تكشفه وتُظهِره؛ وسيعلم الذين ظلموا أيَّ منقلبٍ ينقلبون؛ فستعلمون من هو في ضلالٍ مبين؛ فسوف تعلمون؛ فالعاقبةُ تكشف الحقَّ من الباطل، وتُظهِر المحقَّ من المبطل؛ فاثبت على الحقّ، واصبر، وأيقن بظهورِ الحقّ؛ فمن ثبت على الحقِّ ظهر حقُّه، ومن أبطل ظهر بطلانه؛ فاجعل الثباتَ على الحقِّ واليقينَ بأنّ العاقبةَ تكشفه دأبك."}},{"n":6,"reflection":{"text":"«بأييكم المفتون»: بأيّكم المفتونُ (المجنونُ، أو المُبتلى بالفتنة)؛ ففي هذا بيانُ أنّ الفتنةَ والجنونَ في المكذّبين لا في النبيِّ ﷺ؛ فاعلم أنّ المفتونَ من ضلّ عن الحقّ، فالمفتونُ هو التاركُ للحقّ، فالزم الحقَّ لتسلم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ الحقِّ للسلامةِ من الفتنة، ومعرفةُ أنّ المفتونَ التاركُ للحق."},"action":{"text":"تأمّل من هو المفتون: بأيّكم المفتونُ، أي في أيِّ الفريقين يكون المفتونُ (المجنونُ، أو المُبتلى بالجنونِ والضلال)؟ أفيكم أم في النبيِّ ﷺ؟ والجوابُ ظاهر: أنّ الفتنةَ والضلالَ في المكذّبين لا في النبيِّ «بأييكم المفتون»؛ ففي هذا بيانُ أنّ المفتونَ (الضالَّ عن الحقّ) هو من كذّب الرسولَ لا الرسولُ نفسه، فرمَوه بما هم أولى به؛ فالمفتونُ التاركُ للحق؛ فاعلم أنت أنّ المفتونَ الحقيقيَّ من ضلّ عن الحقِّ وتركه، لا من اتّبعه؛ فالزم الحقَّ لتسلم من الفتنة؛ إنّ ربّك هو أعلمُ بمن ضلّ عن سبيله؛ ومن يُضلِلِ الله فما له من هاد؛ فالمفتونُ من ضلّ عن الحقّ، والسالمُ من لزمه؛ فالزم الحقَّ واتّبعه، ولا تفارقه، لتسلم من الفتنةِ والضلال؛ فمن لزم الحقَّ سلم، ومن تركه افتُتِن؛ فاجعل لزومَ الحقِّ للسلامةِ من الفتنةِ ومعرفةَ أنّ المفتونَ التاركُ للحقِّ دأبك."}},{"n":7,"reflection":{"text":"«إن ربك هو أعلم بمن ضل عن سبيله وهو أعلم بالمهتدين»: إنّ ربّك هو أعلمُ بمن ضلّ عن سبيله وهو أعلمُ بالمهتدين؛ ففي هذا تفويضُ الحكمِ إلى الله العليمِ بالضالِّ والمهتدي؛ فاطلب الهدايةَ من الله واجتهد فيها، فالله يعلم الضالَّ من المهتدي، فاطلب أن تكون من المهتدين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الهدايةِ من الله، والاجتهادُ لتكون من المهتدين."},"action":{"text":"تأمّل علمَ الله بالفريقين: إنّ ربّك هو أعلمُ بمن ضلّ عن سبيله (فحاد عن الحقّ)، وهو أعلمُ بالمهتدين (الذين لزموا الحقّ)؛ فهو العالمُ بحالِ الفريقين، المجازي لكلٍّ بما يستحقّ «إن ربك هو أعلم بمن ضل عن سبيله وهو أعلم بالمهتدين»؛ ففي هذا تفويضُ الأمرِ إلى الله العليمِ بالضالِّ والمهتدي، وتسليةٌ للنبيِّ ﷺ بأنّ الله يعلم حاله وحالَ مكذّبيه؛ فالله أعلمُ بالمهتدين فيوفّقهم، وبالضالّين فيخذلهم؛ فاطلب أنت الهدايةَ من الله، واجتهد في أسبابها، لتكون من المهتدين الذين يعلمهم؛ اهدنا الصراطَ المستقيم؛ ومن يهدِ الله فهو المهتد؛ والذين اهتدوا زادهم هدًى؛ فالله أعلمُ بالضالِّ والمهتدي، والهدايةُ بيده؛ فاطلبها منه، واجتهد في أسبابها (الإيمانِ والعملِ والدعاء)؛ فمن طلب الهدايةَ واجتهد هُدِي، ومن أعرض ضلّ؛ فاجعل طلبَ الهدايةِ من الله والاجتهادَ لتكون من المهتدين دأبك."}}]},{"title":"النهيُ عن طاعةِ المكذّبين وذمُّ الأثيمِ الحلّاف","range":[8,16],"theme":"النهيُ عن طاعةِ المكذّبين والمداهنةِ في الدين «ودوا لو تدهن فيدهنون»، وذمِّ صفاتِ الأثيمِ الحلّافِ المهين: الهمازِ المشّاءِ بنميم، المنّاعِ للخيرِ المعتدي الأثيم، العتلِّ الزنيم، الذي أطغاه المالُ والبنون فردّ الآياتِ «أساطير الأولين»، ووعيدِه «سنسمه على الخرطوم»","verses":[{"n":8,"reflection":{"text":"«فلا تطع المكذبين»: فلا تُطِع، يا محمد، المكذّبين بالحقّ فيما يدعونك إليه؛ ففي هذا النهيُ عن طاعةِ المكذّبين؛ فلا تُطِع من يكذّب بالحقِّ ولو أغراك، فطاعةُ المكذّبين مفارقةٌ للحقّ، فاثبت ولا تُطِعهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ طاعةِ المكذّبين، والثباتُ على الحقّ."},"action":{"text":"تأمّل النهيَ عن طاعةِ المكذّبين: فلا تُطِع، يا محمد، المكذّبين (بالله ورسولِه والحقّ) فيما يدعونك إليه من مداهنةٍ أو مداراةٍ على حسابِ الدين، أو تركِ بعضِ الحقّ «فلا تطع المكذبين»؛ ففي هذا النهيُ عن طاعةِ المكذّبين ومسايرتهم في باطلهم، أمرًا للنبيِّ ﷺ وأمّته؛ فطاعةُ المكذّبين مفارقةٌ للحقّ؛ فلا تُطِع أنت من يكذّب بالحقِّ ولو أغراك أو ساومك؛ ولا تُطِع من أغفلنا قلبه عن ذكرنا؛ ولا تُطِع منهم آثمًا أو كفورًا؛ فاصبر لحكمِ ربّك ولا تُطِع منهم آثمًا أو كفورًا؛ فطاعةُ المكذّبين تجرّ إلى الباطلِ ومفارقةِ الحقّ؛ فلا تُطِعهم، واثبت على الحقّ، ولا تُساومهم عليه؛ فمن لم يُطِع المكذّبين ثبت، ومن أطاعهم زلّ؛ فاجعل عدمَ طاعةِ المكذّبين والثباتَ على الحقِّ دأبك."}},{"n":9,"reflection":{"text":"«ودوا لو تدهن فيدهنون»: تمنّى المكذّبون لو تُلِين لهم وتُداهنهم في دينك فيُلِينون لك ويُداهنونك؛ ففي هذا كشفُ مطلبِ المكذّبين: المداهنةُ في الدين؛ فلا تُداهن في دينِ الله ولا تُساوم على الحقّ، فالمداهنةُ في الدينِ خيانة، فاثبت على الحقّ كاملًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ المداهنةِ في الدين، والثباتُ على الحقِّ كاملًا."},"action":{"text":"تأمّل مطلبَ المداهنة: ودّوا (تمنّى المكذّبون) لو تُدهِن، أي تُلِين لهم وتُساهلهم وتترك بعضَ دينك أو تنافقهم في الحقّ، فيُدهِنون، أي فيُلِينون لك ويُساهلونك مقابلَ ذلك «ودوا لو تدهن فيدهنون»؛ ففي هذا كشفُ مطلبِ المكذّبين: أنهم يريدون مداهنةَ النبيِّ ﷺ في الدين (بترك بعضِ الحقّ) ليُداهنوه، وهي مساومةٌ باطلة؛ فالمداهنةُ في الدينِ خيانةٌ للحقّ؛ فلا تُداهن أنت في دينِ الله، ولا تُساوم على شيءٍ من الحقّ إرضاءً لأحد؛ ولا تركنوا إلى الذين ظلموا فتمسّكم النار؛ وإن كادوا ليفتنونك عن الذي أوحينا إليك؛ ودّوا لو تُدهِن فيُدهِنون؛ فالمداهنةُ في الدينِ (تركُ بعضِ الحقِّ إرضاءً للباطل) خيانةٌ ومزلّة؛ فاثبت على الحقِّ كاملًا، ولا تُداهن ولا تُساوم عليه؛ فمن لم يُداهن في الدينِ ثبت، ومن داهن زلّ؛ فاجعل تركَ المداهنةِ في الدينِ والثباتَ على الحقِّ كاملًا دأبك."}},{"n":10,"reflection":{"text":"«ولا تطع كل حلاف مهين»، ولا تُطِع كلَّ كثيرِ الحلفِ (بالباطل) حقيرٍ مهين؛ ففي هذا النهيُ عن طاعةِ الحلّافِ المهين، وذمُّ كثرةِ الحلف؛ فاحذر كثرةَ الحلفِ ولا تُطِع الحلّافَ المهين، فكثرةُ الحلفِ مهانة، فأقلِل من الحلف.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقلالُ من الحلف، وعدمُ طاعةِ الحلّافِ المهين."},"action":{"text":"تأمّل ذمَّ الحلّاف: ولا تُطِع كلَّ حلّافٍ، أي كثيرِ الحلفِ بالله في الحقِّ والباطل (وكثرةُ الحلفِ دليلُ الاستخفافِ بالله أو الكذب)؛ مهينٍ، أي حقيرٍ ضعيفِ الرأيِ مهانٍ (لكثرةِ كذبه وشرّه) «ولا تطع كل حلاف مهين»؛ ففي هذا النهيُ عن طاعةِ الحلّافِ الكذّابِ المهين، وذمُّ كثرةِ الحلف؛ فكثرةُ الحلفِ (خاصّةً بالباطل) مهانةٌ ونقص؛ فأقلِل أنت من الحلف، ولا تُطِع الحلّافَ المهين ولا تقتدِ به؛ ولا تجعلوا الله عرضةً لأيمانكم؛ واحفظوا أيمانكم؛ ولا تطع كلَّ حلّافٍ مهين؛ فكثرةُ الحلفِ استخفافٌ باسمِ الله ومظنّةُ الكذب، ومهانةٌ لصاحبها؛ فأقلِل من الحلف، ولا تحلف إلا صادقًا عند الحاجة، ولا تُطِع الحلّافين؛ فمن أقلّ الحلفَ وصدق أُكرِم، ومن أكثره بالباطلِ هان؛ فاجعل الإقلالَ من الحلفِ وعدمَ طاعةِ الحلّافِ المهينِ دأبك."}},{"n":11,"reflection":{"text":"«هماز مشاء بنميم»: همّازٍ (كثيرِ العيبِ للناسِ والطعنِ فيهم) مشّاءٍ بنميمٍ (ينقل الكلامَ بين الناسِ للإفساد)؛ ففي هذا ذمُّ الهمزِ والنميمة؛ فاحذر عيبَ الناسِ والنميمةَ بينهم، فالهمزُ والنميمةُ من صفاتِ الأشرار، فاجتنبهما.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ الهمزِ والنميمة، وحفظُ اللسانِ عن أذى الناس."},"action":{"text":"تأمّل ذمَّ الهمزِ والنميمة: همّازٍ، أي كثيرِ الهمز (عيبِ الناسِ والطعنِ فيهم والاغتيابِ لهم بالقولِ والإشارة)؛ مشّاءٍ بنميمٍ، أي كثيرِ المشيِ بالنميمةِ (نقلِ الكلامِ بين الناسِ ليُفسِد بينهم ويُوقِع العداوة) «هماز مشاء بنميم»؛ ففي هذا ذمُّ الهمّازِ (عيّابِ الناس) والنمّامِ (الساعي بالفساد)، من صفاتِ الحلّافِ المهين؛ فالهمزُ والنميمةُ من كبائرِ اللسانِ ومن صفاتِ الأشرار؛ فاحذر أنت عيبَ الناسِ والطعنَ فيهم، والنميمةَ بينهم؛ ويلٌ لكلِّ همزةٍ لمزة؛ ولا يغتب بعضكم بعضًا؛ لا يدخل الجنّةَ نمّام؛ فالهمزُ والنميمةُ يفسدان بين الناسِ ويوجبان العذاب؛ فاجتنبهما، واحفظ لسانك عن أذى الناسِ وعيبهم ونقلِ كلامهم؛ فمن حفظ لسانه سلم، ومن همز ونمّ أثم؛ فاجعل اجتنابَ الهمزِ والنميمةِ وحفظَ اللسانِ عن أذى الناسِ دأبك."}},{"n":12,"reflection":{"text":"«مناع للخير معتد أثيم»: منّاعٍ للخير (يمنع المعروفَ والحقوق) معتدٍ (متجاوزٍ للحدود) أثيمٍ (كثيرِ الآثام)؛ ففي هذا ذمُّ منعِ الخيرِ والاعتداءِ والإثم؛ فاحذر منعَ الخيرِ والاعتداءَ والإثم، فهذه صفاتُ الأشرار، فابذل الخيرَ واجتنب الاعتداءَ والإثم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"بذلُ الخير، واجتنابُ الاعتداءِ والإثم."},"action":{"text":"تأمّل ذمَّ منعِ الخير: منّاعٍ للخير، أي كثيرِ المنعِ للمعروفِ والحقوقِ والصدقةِ والنفعِ للناس؛ معتدٍ، أي متجاوزٍ للحدودِ في الظلمِ والعدوانِ على الناس؛ أثيمٍ، أي كثيرِ الإثمِ والمعاصي «مناع للخير معتد أثيم»؛ ففي هذا ذمُّ من يمنع الخيرَ عن الناس، ويعتدي عليهم، ويُكثِر الآثام، من صفاتِ الحلّافِ المهين؛ فمنعُ الخيرِ والاعتداءُ والإثمُ من صفاتِ الأشرار؛ فاحذر أنت منعَ الخيرِ والمعروفِ عن الناس، والاعتداءَ عليهم، والإكثارَ من الإثم؛ الذين يبخلون ويأمرون الناسَ بالبخل؛ ولا تعتدوا إنّ الله لا يحبّ المعتدين؛ ويسارعون في الإثمِ والعدوان؛ فمنعُ الخيرِ والاعتداءُ والإثمُ صفاتُ الأشقياء؛ فابذل الخيرَ والمعروف، واجتنب الاعتداءَ على الناس، وأقلِل من الإثم؛ فمن بذل الخيرَ وكفّ أذاه أفلح، ومن منع الخيرَ واعتدى وأثم خسر؛ فاجعل بذلَ الخيرِ واجتنابَ الاعتداءِ والإثمِ دأبك."}},{"n":13,"reflection":{"text":"«عتل بعد ذلك زنيم»: عُتُلٍّ (جافٍ غليظٍ فظّ) بعد ذلك (مع تلك الصفاتِ الذميمة) زنيمٍ (دعيٍّ ملصَقٍ بقومٍ ليس منهم، أو معروفٍ بالشرّ)؛ ففي هذا تمامُ ذمِّ الأثيم؛ فاحذر الجفاءَ والفظاظةَ وسوءَ الأصل، فهذه صفاتُ الأشرار، فتخلّق بضدّها من اللينِ وطيبِ الأصل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التخلّقُ باللينِ وطيبِ الخُلق، واجتنابُ الجفاءِ والفظاظة."},"action":{"text":"تأمّل تمامَ ذمِّ الأثيم: عُتُلٍّ، أي غليظٍ جافٍ فظٍّ شديدِ الخصومة، أو أكولٍ شروبٍ منوعٍ للخير؛ بعد ذلك (مع تلك الصفاتِ القبيحة) زنيمٍ، أي دعيٍّ ملصَقٍ في نسبٍ ليس منه، أو معروفٍ بالشرِّ كما تُعرَف الشاةُ بزنمتها «عتل بعد ذلك زنيم»؛ ففي هذا تمامُ ذمِّ الأثيمِ الحلّافِ بوصفه بالجفاءِ والغلظةِ وسوءِ الأصلِ أو الشهرةِ بالشرّ؛ فالجفاءُ والفظاظةُ من صفاتِ الأشرار؛ فاحذر أنت الجفاءَ والفظاظةَ والغلظةَ في المعاملة، وتخلّق بضدّها من اللينِ والرحمةِ وحسنِ الخُلق؛ ولو كنتَ فظًّا غليظَ القلبِ لانفضّوا من حولك؛ فبما رحمةٍ من الله لنتَ لهم؛ فالجفاءُ والغلظةُ تنفّر الناس، واللينُ يجمعهم؛ فتخلّق باللينِ وحسنِ الخُلق، واجتنب الجفاءَ والفظاظة، وكن كريمَ الخُلق؛ فمن لان وحسن خُلقه أُحِبّ، ومن جفا وغلظ نُفِر منه؛ فاجعل التخلّقَ باللينِ وطيبِ الخُلقِ واجتنابَ الجفاءِ والفظاظةِ دأبك."}},{"n":14,"reflection":{"text":"«أن كان ذا مال وبنين»: أطغاه أن كان ذا مالٍ وبنين حتى كذّب بالحقّ؟ ففي هذا بيانُ أنّ المالَ والولدَ قد يُطغيان صاحبهما؛ فلا تدع المالَ والولدَ يُطغيانك عن الحقّ، فالمالُ والولدُ فتنةٌ قد تُطغي، فاحذر طغيانهما.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من إطغاءِ المالِ والولد، وشكرُهما بالطاعة."},"action":{"text":"تأمّل إطغاءَ المالِ والولد: أن كان ذا مالٍ وبنين، أي أطغاه كونه ذا مالٍ وبنين، فاستكبر وكذّب بآياتِ الله وطلب المزيد، أو: أتُطيعه لأنه ذو مالٍ وبنين؟ فجعل نعمةَ المالِ والولدِ سببًا للكفرِ والطغيان «أن كان ذا مال وبنين»؛ ففي هذا بيانُ أنّ المالَ والبنين أطغيا هذا الأثيمَ حتى كذّب بالحقّ، فجعل النعمةَ سببَ الكفرِ بدل الشكر؛ فالمالُ والولدُ فتنةٌ قد تُطغي صاحبها؛ فلا تدع أنت المالَ والولدَ يُطغيانك عن الحقِّ وطاعةِ الله، بل اشكرهما بالطاعة؛ كلّا إنّ الإنسانَ ليطغى * أن رآه استغنى؛ وما أموالكم ولا أولادكم بالتي تقرّبكم عندنا زلفى؛ ذرني ومن خلقتُ وحيدًا وجعلتُ له مالًا ممدودًا؛ فالمالُ والولدُ نعمةٌ قد تُطغي إن لم تُشكَر؛ فاشكرهما بطاعةِ الله، ولا تدعهما يُطغيانك عن الحقّ؛ فمن شكر نعمتهما ولم يطغَ أفلح، ومن أطغياه خسر؛ فاجعل الحذرَ من إطغاءِ المالِ والولدِ وشكرَهما بالطاعةِ دأبك."},"qadiyya":{"title":"قضيّةُ سببِ النزول: أهو حصرٌ للآية أم بيانٌ لقاعدتها؟","question":"قال الله: ﴿وَلَا تُطِعْ كُلَّ حَلَّافٍ مَهِينٍ﴾ إلى قوله: ﴿عُتُلٍّ بَعْدَ ذَٰلِكَ زَنِيمٍ﴾، ثمّ قال: ﴿أَنْ كَانَ ذَا مَالٍ وَبَنِينَ﴾ ﴿إِذَا تُتْلَىٰ عَلَيْهِ آيَاتُنَا قَالَ أَسَاطِيرُ الْأَوَّلِينَ﴾.\nوقد ذُكر أنّ هذه الآيات نزلت في رجلٍ بعينه من المشركين، وقد مضى الرجلُ وانقضى قرنُه.\nفالقضيّة: هل تنقطع الآيةُ بانقضاء من نزلت فيه؟ ثمّ: ما وظيفةُ ذكر الشخص المعيّن إن لم تكن التضييق؟ ثمّ: ما الضابطُ الذي يدخل به غيرُه فيها؟","background":"ولا يستقيم الجوابُ حتى يفرَّق بين أمرين:\nالأوّل: ما نزلت الآيةُ فيه، وهو واقعةٌ معيّنةٌ في زمنٍ معيّن.\nوالثاني: ما تناولته الآيةُ بحكمها، وهو ما دلّ عليه لفظُها.\nفالأوّلُ خبر، والثاني حكم، وليس بينهما تلازمٌ في السعة والضيق؛ فيكون النصُّ **خاصًّا في مورده، عامًّا في لفظه**.\nثمّ يُنظر في اللفظ نفسِه: فالآياتُ ها هنا لم تجرِ على اسمٍ ولا نسب، بل على أوصافٍ متتابعة: الحلف والمهانة والهمز والنميمة ومنع الخير والاعتداء والإثم والغلظة.\nوالوصفُ يقع في غير من وقع فيه أوّلًا، **والاسمُ لا يقع**.","what_happened":"⭐ قدّم السعديُّ الأصلَ قبل أن يبلغ الآية، فقال عند قوله ﴿فَلَا تُطِعِ الْمُكَذِّبِينَ﴾: «وهذا عام في كل مكذب، وفي كل طاعة ناشئة عن التكذيب، وإن كان السياق في شيء خاص»، ثمّ ذكر ذلك السياق: «وهو أن المشركين طلبوا من النبي صلى الله عليه وسلم، أن يسكت عن عيب آلهتهم ودينهم، ويسكتوا عنه».\nثمّ لمّا فرغ من تعداد الأوصاف جمعها في حاصلٍ واحد، وخصّ منها ما خصّ، فقال: «وحاصل هذا، أن الله تعالى نهى عن طاعة كل حلاف كذاب، خسيس النفس، سيئ الأخلاق، خصوصًا الأخلاق المتضمنة للإعجاب بالنفس، والتكبر على الحق وعلى الخلق، والاحتقار للناس، كالغيبة والنميمة، والطعن فيهم، وكثرة المعاصي».\n⭐ ثمّ ساق سببَ النزول والحكمَ في نَفَسٍ واحد، فابتدأ بقوله: «وهذه الآيات»، ثمّ اعترض بالسبب: «وإن كانت نزلت في بعض المشركين، كالوليد بن المغيرة أو غيره لقوله عنه»، وساق ﴿أَنْ كَانَ ذَا مَالٍ وَبَنِينَ﴾ ﴿إِذَا تُتْلَىٰ عَلَيْهِ آيَاتُنَا قَالَ أَسَاطِيرُ الْأَوَّلِينَ﴾، ثمّ قال: «أي: لأجل كثرة ماله وولده، طغى واستكبر عن الحق، ودفعه حين جاءه، وجعله من جملة أساطير الأولين، التي يمكن صدقها وكذبها».\n⭐ ثمّ جاء تمامُ الكلام بعد الاعتراض: «فإنها عامة في كل من اتصف بهذا الوصف، لأن القرآن نزل لهداية الخلق كلهم، ويدخل فيه أول الأمة وآخرهم».\nثمّ قرّر وظيفة السبب فقال: «وربما نزل بعض الآيات في سبب أو في شخص من الأشخاص، لتتضح به القاعدة العامة، ويعرف به أمثال الجزئيات الداخلة في القضايا العامة».","the_verdict":"فالحاصلُ أنّ سببَ النزول عنده جزئيّةٌ توضّح القاعدة، لا قيدٌ يحبسها.\nوموضعُ الدقّة أنّ العمومَ في كلامه لم يأتِ حكمًا لاحقًا طارئًا على الخبر، بل جاء تمامًا لجملةٍ واحدة، والسببُ معترضٌ في وسطها؛ فلم ينفكّ عنده أحدُهما عن الآخر. وقد ساق ﴿أَنْ كَانَ ذَا مَالٍ وَبَنِينَ﴾ دليلًا على التعيين إذ قال «لقوله عنه»، فكانت الآيةُ عنده أمارةَ نزولٍ في معيَّن، ثمّ حكم مع ذلك بالعموم.\nثمّ لم يترك العمومَ دعوى، بل علّله بمقصود الإنزال: «لأن القرآن نزل لهداية الخلق كلهم، ويدخل فيه أول الأمة وآخرهم». فلو قُصرت الآيةُ على من نزلت فيه لخرج من هدايتها كلُّ من لم يشهد التنزيل، فيبطل بالتضييق المقصودُ من الإنزال نفسِه.\n⭐ وأمّا وظيفةُ ذكر الشخص فقد نصّ عليها: «لتتضح به القاعدة العامة، ويعرف به أمثال الجزئيات الداخلة في القضايا العامة»؛ فالجزئيّةُ موضعُ إيضاحٍ لا موضعُ حصر.\nوأمّا الضابطُ الذي يدخل به غيرُه، فهو الذي قيّده بلفظه: «كل من اتصف بهذا الوصف»، **فالمدارُ على الاتّصاف**. وقد بيّن الوصفَ في حاصله، وخصّ منه الأخلاقَ المتضمّنةَ للإعجاب بالنفس والتكبّر على الحقّ والاحتقار للناس. وأمّا انقطاعُ الزمان عن الحكم فمأخوذٌ من تعليله: «ويدخل فيه أول الأمة وآخرهم».\n⭐ ومن ها هنا يقع الغلطُ من جهتين متقابلتين:\nفالأولى: أن يُقرأ سببُ النزول قراءةَ خبرٍ عن ماضٍ، فيصير الذمُّ ترجمةً لرجلٍ مضى، ويمرّ القارئُ بالأوصاف ولا يعرضها على نفسه.\nوالثانية: أن يُؤخذ العمومُ ويُترك قيدُه، فيُرمى بالوصف من لم يثبت اتّصافُه به. والعمومُ إنّما جاء بالوصف؛ فمن أسقط الوصفَ لم يبقَ في يده عموم، **بل بقيت تهمة**.\n⭐ وأمّا تحفّظُه فظاهرٌ في موضعين: قال «أو غيره» فلم يجزم بتعيين الشخص، وذلك جارٍ مع أصله، إذ الحكمُ لمّا لم يتعلّق بالشخص لم يُحتج في تعيينه إلى جزم؛ وقال «وربما نزل بعض الآيات» فلم يجعل ذلك في كلّ آيةٍ لها سبب.","for_you":"فأمّا الذي تخرج به فثلاثة:\nالأوّل: اعرض الوصفَ على نفسك قبل أن تعرضه على أحد. فخذ الأوصاف من ﴿وَلَا تُطِعْ كُلَّ حَلَّافٍ مَهِينٍ﴾ إلى ﴿عُتُلٍّ بَعْدَ ذَٰلِكَ زَنِيمٍ﴾ واحدًا واحدًا، وقف عند كلّ واحدٍ تسأل: أفيَّ منه شيء؟\nوالثاني: إذا مرّ بك سببُ نزولٍ فاسأل أوّلًا: أجرى اللفظُ على وصفٍ أم على اسمٍ وواقعة؟ فإن جرى على وصفٍ فاطلب القاعدة واكتبها في سطرٍ بلفظك. وليس كلُّ سببٍ يجري هذا المجرى، فلا تتكلّف قاعدةً حيث لا تظهر.\nوالثالث: لا تُنزّل آيةَ ذمٍّ على معيّنٍ حتى تذكر الوصف ودليلَ ثبوته فيه. فإن حضرك الوصفُ ولم يحضرك دليلُه فأمسك؛ فقد أخذتَ العمومَ وتركتَ ما قام به.","grade":"ma'thur","source":"تفسيرُ السعديّ لسورة القلم: تقريرُه العمومَ عند ﴿فَلَا تُطِعِ الْمُكَذِّبِينَ﴾ («وهذا عام في كل مكذب») مع ذكر السياق الخاصّ («وهو أن المشركين طلبوا»)، وحاصلُه بعد تعداد الأوصاف مع تخصيصه أخلاقَ الكِبر («وحاصل هذا، أن الله تعالى نهى عن طاعة كل حلاف كذاب»)، وسَوقُه سببَ النزول معترضًا («وإن كانت نزلت في بعض المشركين») مع استدلاله عليه («لقوله عنه»)، وتفسيرُه ﴿أَنْ كَانَ ذَا مَالٍ وَبَنِينَ﴾ («أي: لأجل كثرة ماله وولده»)، وتمامُ كلامه بالعموم وتعليله («فإنها عامة في كل من اتصف بهذا الوصف»)، وتقريرُه وظيفةَ السبب («وربما نزل بعض الآيات في سبب أو في شخص من الأشخاص»): كلُّها بنصّها في تفسير السعديّ (٦٨:٨ و٦٨:١٣ و٦٨:١٤).","honesty":"وممّا يجب أن يُقال:\nتفريقُنا في التمهيد بين ما نزلت فيه الآيةُ وما تناولته، وقولُنا إنّ الخطاب جرى على أوصافٍ لا على اسم، تمهيدٌ منّا لتقريب كلامه، وليس نصًّا له، وإن كان مبنيًّا على قوله «كل من اتصف بهذا الوصف».\nوجمعُنا بين ثلاثة مواضع له في السورة، عند ﴿فَلَا تُطِعِ الْمُكَذِّبِينَ﴾ وعند ﴿عُتُلٍّ بَعْدَ ذَٰلِكَ زَنِيمٍ﴾ وعند ﴿أَنْ كَانَ ذَا مَالٍ وَبَنِينَ﴾، وقولُنا إنّه قدّم الأصلَ قبل أن يبلغ الآية، ملاحظةٌ منّا على صنيعه. وكذلك وصفُنا كلامَه بأنّ السبب فيه معترضٌ في وسط جملةٍ واحدة، فهو تحليلٌ منّا لتركيب عبارته.\nوقولُنا إنّ التضييق يُبطل المقصودَ من الإنزال، استنباطٌ منّا من علّته المذكورة، ولم يقله بهذا اللفظ.\nوكذلك الغلطان اللذان ذكرناهما، وقولُنا إنّ من أسقط الوصفَ بقيت في يده تهمة، استنباطٌ منّا لا نقلٌ عنه. وكذلك ربطُنا بين تردّده في تعيين الشخص وبين كون الحكم غير متعلّقٍ به؛ ولذلك لم ننسب إليه الجزمَ بأنّ كلّ سببٍ يجري هذا المجرى.\nوأمّا الثلاثةُ التي ختمنا بها، وهي عرضُ الوصف على النفس، والسؤالُ عن القاعدة، والتوقّفُ عن تنزيل الذمّ على معيَّنٍ حتى يثبت الوصف، فأعمالٌ منّا مبنيّةٌ على قوله «كل من اتصف بهذا الوصف»، ولم يأمر بشيءٍ منها، ولا تكلّم في تنزيل النصوص على الأعيان.\nوالمسألةُ في أصلها مسألةُ العبرة بعموم اللفظ لا بخصوص السبب، وقد جرينا فيها على اختيار السعديّ، ولم نحرّر خلافَ الأصوليّين فيها ولا أدلّةَ المخالف، وهي بابٌ له أهلُه ومظانُّه.\nومن رأى أنّا وسّعنا فليردّه."}},{"n":15,"reflection":{"text":"«إذا تتلى عليه آياتنا قال أساطير الأولين»: إذا تُتلى عليه آياتنا (القرآن) قال: هذه أساطيرُ الأوّلين (أباطيلهم المكتوبة)؛ ففي هذا بيانُ استكبارِ الأثيمِ وردِّه للحقّ؛ فاحذر ردَّ آياتِ الله والاستهزاءَ بها، فردُّ الحقِّ استكبار، فاقبل آياتِ الله وأذعن لها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ آياتِ الله والإذعانُ لها، والحذرُ من ردِّها."},"action":{"text":"تأمّل ردَّ الأثيمِ للحق: إذا تُتلى عليه آياتنا (القرآنُ الذي يُتلى) قال استكبارًا وتكذيبًا: أساطيرُ الأوّلين، أي أباطيلُ الأقدمين وأخبارهم المكتوبةُ التي لا حقيقةَ لها «إذا تتلى عليه آياتنا قال أساطير الأولين»؛ ففي هذا بيانُ استكبارِ الأثيمِ ومقابلتِه آياتِ الله بالردِّ والتكذيبِ ونسبتها إلى أساطيرِ الأوّلين؛ فردُّ الحقِّ والاستهزاءُ به من صفاتِ المكذّبين؛ فاحذر أنت ردَّ آياتِ الله والاستهزاءَ بها أو الطعنَ فيها؛ وإذا تُتلى عليهم آياتنا قالوا قد سمعنا لو نشاء لقلنا مثلَ هذا إن هذا إلا أساطيرُ الأوّلين؛ ويلٌ لكلِّ أفّاكٍ أثيم * يسمع آياتِ الله تُتلى عليه ثم يُصِرّ مستكبرًا؛ فردُّ آياتِ الله واتّهامُها بالأساطيرِ استكبارٌ وكفر؛ فاقبل آياتِ الله، وأذعن لها، وتدبّرها، واعمل بها؛ فمن قبل آياتِ الله وأذعن لها اهتدى، ومن ردّها واستكبر خسر؛ فاجعل قبولَ آياتِ الله والإذعانَ لها والحذرَ من ردِّها دأبك."}},{"n":16,"reflection":{"text":"«سنسمه على الخرطوم»: سنجعل له علامةً على أنفه (الخرطومِ) تُذِلّه وتفضحه؛ ففي هذا وعيدٌ للأثيمِ بالإذلالِ والفضيحة؛ فاحذر أن تُفضَح بذنوبك، فالمستكبرُ يُذَلّ ويُفضَح، فتواضع للحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التواضعُ للحقّ، والحذرُ من إذلالِ الله للمستكبر."},"action":{"text":"تأمّل وعيدَ الأثيم: سنسمه على الخرطومِ، أي سنجعل له علامةً وسمةً على أنفه (سمّاه خرطومًا تحقيرًا كأنف الفيل) تُذِلّه وتفضحه بين الناس في الدنيا والآخرة، جزاءَ استكباره وتكذيبه «سنسمه على الخرطوم»؛ ففي هذا وعيدٌ للأثيمِ المستكبرِ بأنّ الله سيُذِلّه ويفضحه ويُعلِّم عليه علامةً باقية؛ فالمستكبرُ على الحقِّ يُذَلّ ويُفضَح؛ فاحذر أنت الاستكبارَ على الحقّ، والذنوبَ التي تُفضَح بها، وتواضع للحقّ؛ سنسمه على الخرطوم؛ يُعرَف المجرمون بسيماهم؛ ووجوهٌ يومئذٍ عليها غبرة؛ فالمستكبرُ على الحقِّ مصيره الإذلالُ والفضيحةُ في الدنيا والآخرة؛ فتواضع للحقّ، واقبله، واجتنب أسبابَ الفضيحةِ والذلّ؛ فمن تواضع للحقِّ أُكرِم، ومن استكبر أُذِلّ وفُضِح؛ فاجعل التواضعَ للحقِّ والحذرَ من إذلالِ الله للمستكبرِ دأبك."}}]},{"title":"مثلُ أصحابِ الجنّةِ الذين بخلوا فحُرِموا","range":[17,33],"theme":"ابتلاءُ أهلِ مكّةِ بالنعمةِ كأصحابِ الجنّةِ الذين أقسموا ليقطعنّ ثمرها «ولا يستثنون» عازمين على منعِ المساكين، فطاف عليها طائفٌ من ربّك «فأصبحت كالصريم»، ثم صدمتُهم وتلاومُهم واعترافُهم «إنا كنا ظالمين... إنا كنا طاغين» ورجوعُهم «إنا إلى ربنا راغبون»، وأنّ «عذاب الآخرة أكبر لو كانوا يعلمون»؛ ومن دروسها: الاستثناءُ بمشيئةِ الله، وأداءُ حقِّ المساكين، والتذكيرُ بالحقّ","verses":[{"n":17,"reflection":{"text":"«إنا بلوناهم كما بلونا أصحاب الجنة إذ أقسموا ليصرمنها مصبحين»: إنا اختبرنا أهلَ مكّة (بالنعمة) كما اختبرنا أصحابَ الجنّةِ (البستان) إذ أقسموا لَيقطعنّ ثمرها مصبحين (بلا استثناء)؛ ففي هذا مثلٌ لأهلِ مكّة بأصحابِ الجنّةِ في الابتلاءِ بالنعمة؛ فاحذر أن تُبطِرك النعمةُ فتُحرَمها، فالنعمةُ ابتلاء، فاشكرها لتدوم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ النعمةِ لتدوم، والحذرُ من بطرِها."},"action":{"text":"تأمّل مثلَ الابتلاءِ بالنعمة: إنا بلوناهم (أهلَ مكّةَ بالخصبِ والرزق) كما بلونا أصحابَ الجنّةِ (بستانٍ لرجلٍ صالحٍ كان يتصدّق منه، فلمّا مات أراد أبناؤه منعَ الفقراء)؛ إذ أقسموا لَيَصرِمُنّها (يقطعون ثمرها) مصبحين (وقتَ الصباحِ سرًّا عن المساكين) «إنا بلوناهم كما بلونا أصحاب الجنة إذ أقسموا ليصرمنها مصبحين»؛ ففي هذا ضربُ مثلٍ لأهلِ مكّةَ (المُنعَمِ عليهم) بأصحابِ الجنّةِ الذين ابتُلوا بالنعمةِ فبخلوا فحُرِموها؛ فالنعمةُ ابتلاءٌ: أتُشكَر أم يُبطَر بها؟ فاحذر أنت أن تُبطِرك النعمةُ فتمنع حقَّها فتُحرَمها؛ ونبلوكم بالشرِّ والخيرِ فتنة؛ وضرب الله مثلًا قريةً كانت آمنةً مطمئنّةً... فكفرت بأنعمِ الله فأذاقها الله لباسَ الجوعِ والخوف؛ فالنعمةُ ابتلاءٌ يُشكَر لتدوم، أو يُبطَر بها فتزول؛ فاشكر النعمةَ بأداءِ حقّها، ولا تبطر بها، ولا تمنع حقَّ الله فيها؛ فمن شكر النعمةَ دامت، ومن بطر بها زالت؛ فاجعل شكرَ النعمةِ لتدومَ والحذرَ من بطرِها دأبك."}},{"n":18,"reflection":{"text":"«ولا يستثنون»، ولا يقولون: إن شاء الله (لم يستثنوا في أيمانهم، ولم يستثنوا حقَّ المساكين)؛ ففي هذا بيانُ خطئهم في تركِ الاستثناءِ وعزمِهم على المنع؛ فقُل إن شاء الله في عزمك، ولا تنسَ حقَّ الله في نعمتك، فالاستثناءُ أدب، فاجعل مشيئةَ الله في كلِّ أمر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"قولُ «إن شاء الله» في العزم، وإحضارُ مشيئةِ الله."},"action":{"text":"تأمّل تركَهم الاستثناء: ولا يستثنون، أي لم يقولوا في قسمهم: إن شاء الله (فيَكِلوا الأمرَ إلى مشيئته)، أو لم يستثنوا نصيبَ المساكين من الثمر كما كان أبوهم يفعل؛ فعزموا عزمًا جازمًا على المنعِ بلا إحضارِ مشيئةِ الله «ولا يستثنون»؛ ففي هذا بيانُ خطئهم في تركِ الاستثناء (قولِ إن شاء الله)، وفي العزمِ على منعِ حقِّ المساكين؛ فتركُ الاستثناءِ وإحضارِ مشيئةِ الله من الغفلة؛ فقُل أنت «إن شاء الله» في عزمك على المستقبل، وأحضِر مشيئةَ الله في كلِّ أمر، ولا تنسَ حقَّ الله في نعمتك؛ ولا تقولنّ لشيءٍ إني فاعلٌ ذلك غدًا * إلا أن يشاء الله واذكر ربّك إذا نسيت؛ وأنّ إلى ربّك المنتهى؛ فإحضارُ مشيئةِ الله في العزمِ أدبٌ وتوفيق؛ فقُل إن شاء الله، وأحضِر مشيئتَه، وأدِّ حقَّ نعمتك؛ فمن أحضر مشيئةَ الله وُفِّق، ومن جزم بلا استثناءٍ قد يُحرَم؛ فاجعل قولَ «إن شاء الله» في العزمِ وإحضارَ مشيئةِ الله دأبك."}},{"n":19,"reflection":{"text":"«فطاف عليها طائف من ربك وهم نائمون»: فطاف على الجنّةِ عذابٌ من ربّك (نارٌ أو آفةٌ) وهم نائمون؛ ففي هذا بيانُ سرعةِ أخذِ الله للنعمةِ عند البطر؛ فاحذر أن يأتيك عذابُ الله وأنت غافل، فعذابُ الله يأتي بغتة، فراقبه ولا تغفل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أخذِ الله بغتة، وعدمُ الغفلةِ عن عقوبته."},"action":{"text":"تأمّل سرعةَ الأخذ: فطاف عليها (على الجنّةِ ليلًا) طائفٌ من ربّك، أي عذابٌ أحاط بها (نارٌ أحرقتها، أو آفةٌ أهلكتها)؛ وهم نائمون (غافلون لا يشعرون) «فطاف عليها طائف من ربك وهم نائمون»؛ ففي هذا بيانُ سرعةِ أخذِ الله للنعمةِ عند البطرِ ومنعِ الحقّ، وأنّ العذابَ أتاهم وهم غافلون نائمون؛ فعذابُ الله يأتي بغتةً على الغافلين؛ فاحذر أنت أن يأتيك عذابُ الله وأنت غافلٌ نائمٌ عن طاعته؛ أفأمن أهلُ القرى أن يأتيهم بأسنا بياتًا وهم نائمون؛ فأخذناهم بغتةً وهم لا يشعرون؛ أو يأخذهم في تقلّبهم فما هم بمعجزين؛ فعذابُ الله يأتي بغتةً على المُصِرّين الغافلين؛ فراقبه، ولا تغفل عن عقوبته، وأدِّ حقوقه؛ فمن راقب الله ولم يغفل سلم، ومن اغترّ وغفل أُخِذ بغتة؛ فاجعل الحذرَ من أخذِ الله بغتةً وعدمَ الغفلةِ عن عقوبته دأبك."}},{"n":20,"reflection":{"text":"«فأصبحت كالصريم»: فأصبحت الجنّةُ كالليلِ المظلمِ (محترقةً سوداء)، أو كالبستانِ المصرومِ الذي قُطِع ثمره؛ ففي هذا بيانُ زوالِ النعمةِ بالكلّيّة؛ فاعتبر بزوالِ النعمةِ فجأةً واشكر ما عندك، فالنعمةُ تزول بالبطر، فاشكرها لتبقى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بزوالِ النعمة، وشكرُها لتبقى."},"action":{"text":"تأمّل زوالَ النعمة: فأصبحت الجنّةُ (بعد أن كانت خضراءَ مثمرة) كالصريمِ، أي كالليلِ المظلمِ في سوادها من الاحتراق، أو كالبستانِ الذي صُرِم (قُطِع) ثمره فلم يبقَ فيه شيء «فأصبحت كالصريم»؛ ففي هذا بيانُ زوالِ النعمةِ عنهم بالكلّيّةِ في لحظة، فصارت جنّتهم سوداءَ محترقةً لا خيرَ فيها؛ فالنعمةُ تزول بالبطرِ ومنعِ الحقّ؛ فاعتبر أنت بزوالِ النعمةِ فجأةً، واشكر ما عندك من النعمِ لتبقى؛ فأصبحوا في دارهم جاثمين كأن لم يغنوا فيها؛ فأصبح يقلّب كفّيه على ما أنفق فيها وهي خاويةٌ على عروشها؛ فالنعمةُ تزول في لحظةٍ بالبطرِ وكفرانها؛ فاعتبر بزوالها، واشكر نعمك، وأدِّ حقوقها، لتبقى وتزيد؛ فمن شكر النعمةَ بقيت، ومن بطر بها زالت؛ فاجعل الاعتبارَ بزوالِ النعمةِ وشكرَها لتبقى دأبك."}},{"n":21,"reflection":{"text":"«فتنادوا مصبحين»: فنادى بعضهم بعضًا في الصباحِ (للذهابِ إلى الجنّة، وهم لا يعلمون ما حلّ بها)؛ ففي هذا بيانُ غفلتهم عمّا وقع؛ فلا تغترّ بما تظنّه باقيًا فقد يكون زائلًا، فالغافلُ يخطّط لما زال، فراقب الله في تدبيرك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بما يُظنّ باقيًا، ومراقبةُ الله في التدبير."},"action":{"text":"تأمّل غفلتهم: فتنادوا مصبحين، أي نادى بعضهم بعضًا في الصباحِ الباكرِ للانطلاقِ إلى جنّتهم لقطفِ ثمرها، وهم لا يعلمون أنّ الله قد أهلكها ليلًا «فتنادوا مصبحين»؛ ففي هذا بيانُ غفلتهم عمّا وقع بجنّتهم، فخطّطوا وتنادوا لأمرٍ قد زال؛ فالغافلُ يُدبِّر لما ذهب؛ فلا تغترّ أنت بما تظنّه باقيًا من نعمةٍ أو مالٍ فقد يكون زائلًا، وراقب الله في تدبيرك؛ وغرّتهم الحياةُ الدنيا؛ يحسبون أنهم مهتدون؛ فتنادوا مصبحين؛ فالغافلُ يخطّط ويعزم لما قد زال بعلمِ الله؛ فلا تغترّ بالباقي، وأحضِر مشيئةَ الله، وراقبه في تدبيرك، وأدِّ حقوقه؛ فمن راقب الله وأحضر مشيئته وُفِّق، ومن اغترّ وغفل خُذِل؛ فاجعل عدمَ الاغترارِ بما يُظنّ باقيًا ومراقبةَ الله في التدبيرِ دأبك."}},{"n":22,"reflection":{"text":"«أن اغدوا على حرثكم إن كنتم صارمين»: أن اذهبوا مبكّرين إلى حرثكم (بستانكم) إن كنتم عازمين على قطعِ ثمره؛ ففي هذا بيانُ عزمِهم على المنعِ والحصاد؛ فاحذر العزمَ على منعِ الخيرِ، فالعزمُ على منعِ الحقِّ عقوبته الحرمان، فاعزم على البذلِ لا المنع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العزمُ على بذلِ الخيرِ لا منعِه، والحذرُ من نيّةِ المنع."},"action":{"text":"تأمّل عزمَهم على المنع: أن اغدوا (اذهبوا مبكّرين) على حرثكم (بستانكم وثمركم) إن كنتم صارمين (عازمين على قطعِ الثمرِ وحصاده)، وقالوا ذلك يحرّض بعضهم بعضًا على البكورِ لمنعِ المساكين «أن اغدوا على حرثكم إن كنتم صارمين»؛ ففي هذا بيانُ عزمهم الجازمِ على الغدوِّ لقطعِ ثمرهم ومنعِ المساكين منه؛ فكان عزمهم على منعِ الخيرِ سببَ حرمانهم؛ فاحذر أنت العزمَ على منعِ الخيرِ عن مستحقّيه، فالنيّةُ السيّئةُ في منعِ الحقّ عقوبتها الحرمان؛ الذين يبخلون ويأمرون الناسَ بالبخل؛ ولا يحضّ على طعامِ المسكين؛ فاعزم على بذلِ الخيرِ لا منعِه؛ فالعزمُ على منعِ حقِّ الله والمساكين سبيلُ الحرمان؛ فاعزم على البذلِ والإحسان، وأدِّ حقوقَ نعمتك، ولا تعزم على المنع؛ فمن عزم على البذلِ بُورِك له، ومن عزم على المنعِ حُرِم؛ فاجعل العزمَ على بذلِ الخيرِ لا منعِه والحذرَ من نيّةِ المنعِ دأبك."}},{"n":23,"reflection":{"text":"«فانطلقوا وهم يتخافتون»: فانطلقوا إلى جنّتهم وهم يتسارّون بينهم (بخفاءٍ لئلا يسمعهم أحد)؛ ففي هذا بيانُ تآمرهم على منعِ الخير؛ فاحذر التآمرَ على منعِ الخيرِ أو الإثم، فالتناجي بالإثمِ سبيلُ الشؤم، فاجعل تناجيك في الخير.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ التآمرِ على المنعِ والإثم، وجعلُ التناجي في الخير."},"action":{"text":"تأمّل تآمرَهم: فانطلقوا (إلى جنّتهم) وهم يتخافتون، أي يتسارّون ويتحدّثون بينهم سرًّا بصوتٍ خفيّ، لئلا يعلم بهم أحدٌ من المساكين فيتبعوهم «فانطلقوا وهم يتخافتون»؛ ففي هذا بيانُ تآمرهم وتناجيهم سرًّا على منعِ الخيرِ عن المساكين؛ فكان تناجيهم بالإثمِ والمنعِ سببَ شؤمهم؛ فاحذر أنت التآمرَ والتناجي على منعِ الخيرِ أو على الإثم؛ إنما النجوى من الشيطانِ ليحزن الذين آمنوا؛ ويتناجون بالإثمِ والعدوان؛ وتناجوا بالبرِّ والتقوى؛ فالتناجي بالإثمِ ومنعِ الخيرِ سبيلُ الشؤمِ والحرمان؛ فاجعل تناجيك في الخيرِ والبرِّ والتقوى، لا في المنعِ والإثم؛ فمن تناجى بالخيرِ أُجِر، ومن تناجى بالإثمِ والمنعِ خُذِل؛ فاجعل تركَ التآمرِ على المنعِ والإثمِ وجعلَ التناجي في الخيرِ دأبك."}},{"n":24,"reflection":{"text":"«أن لا يدخلنها اليوم عليكم مسكين»: يتناجون: أن لا يدخلنّ الجنّةَ اليومَ عليكم مسكينٌ (يطلب حقَّه)؛ ففي هذا بيانُ بخلهم وحرمانهم المساكين؛ فاحذر منعَ المساكينِ حقَّهم، فمنعُ المساكينِ سبيلُ العقوبة، فأطعمهم وأحسِن إليهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إطعامُ المساكينِ والإحسانُ إليهم، والحذرُ من منعهم."},"action":{"text":"تأمّل بخلَهم بالمساكين: يتناجون فيما بينهم: أن لا يدخلنّها (الجنّةَ) اليومَ عليكم مسكينٌ، أي احرصوا ألّا يدخل عليكم فقيرٌ يطلب من ثمرها كما كان يفعل في زمنِ أبيكم الصالح «أن لا يدخلنها اليوم عليكم مسكين»؛ ففي هذا بيانُ بخلهم الشديدِ وعزمهم على حرمانِ المساكين حقَّهم الذي كان أبوهم يعطيهم إيّاه؛ فكان منعُ المساكين سببَ هلاكِ جنّتهم؛ فاحذر أنت منعَ المساكينِ والفقراءِ حقَّهم، وبادر بإطعامهم والإحسانِ إليهم؛ ولا يحضّ على طعامِ المسكين؛ فذلك الذي يدعّ اليتيم * ولا يحضّ على طعامِ المسكين؛ وفي أموالهم حقٌّ للسائلِ والمحروم؛ فمنعُ المساكين حقَّهم سبيلُ العقوبةِ وزوالِ النعمة؛ فأطعمهم، وأحسِن إليهم، وأدِّ حقوقهم في مالك؛ فمن أطعم المساكين وأحسن إليهم بُورِك له، ومن منعهم حُرِم؛ فاجعل إطعامَ المساكينِ والإحسانَ إليهم والحذرَ من منعهم دأبك."}},{"n":25,"reflection":{"text":"«وغدوا على حرد قادرين»، وغدوا مبكّرين على منعٍ وشدّةٍ (على المساكين)، ظانّين أنهم قادرون على قطعِ الثمرِ ومنعه؛ ففي هذا بيانُ اغترارهم بقدرتهم؛ فلا تغترّ بقدرتك على منعِ الخير، فقدرةُ العبدِ لا تُغني عن قدرةِ الله، فاعتمد على الله لا على قدرتك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بالقدرة، والاعتمادُ على الله."},"action":{"text":"تأمّل اغترارَهم بقدرتهم: وغدوا (ذهبوا مبكّرين) على حَرْدٍ، أي على منعٍ وشدّةٍ وقصدٍ للمساكين بالحرمان، أو على غضبٍ وحنق؛ قادرين، أي وهم يظنّون أنهم قادرون على تنفيذِ ما عزموا عليه من القطعِ والمنع «وغدوا على حرد قادرين»؛ ففي هذا بيانُ اغترارهم بقدرتهم على منعِ الخيرِ وقطعِ الثمر، وهم لا يعلمون أنّ الله أهلك جنّتهم؛ فقدرتهم المزعومةُ لا تُغني عن قدرةِ الله؛ فلا تغترّ أنت بقدرتك على منعِ الخيرِ أو على أيِّ أمر، فقدرةُ العبدِ لا شيءَ أمام قدرةِ الله؛ وظنّوا أنهم مانعتهم حصونهم من الله؛ أيحسب أن لن يقدر عليه أحد؛ فقدرةُ العبدِ محدودةٌ لا تُغني عن قدرةِ الله؛ فلا تغترّ بقدرتك، واعتمد على الله، وأحضِر مشيئتَه؛ فمن اعتمد على الله وأحضر مشيئته وُفِّق، ومن اغترّ بقدرته خُذِل؛ فاجعل عدمَ الاغترارِ بالقدرةِ والاعتمادَ على الله دأبك."}},{"n":26,"reflection":{"text":"«فلما رأوها قالوا إنا لضالون»: فلمّا رأوا الجنّةَ محترقةً قالوا: إنا لضالّون (أخطأنا الطريقَ، أو ضللنا عن الصواب)؛ ففي هذا بيانُ صدمتهم عند رؤيةِ العاقبة؛ فاعتبر بعاقبةِ من منع الخيرَ قبل أن تصدم بها، فعاقبةُ منعِ الخيرِ الحرمان، فابذل الخير.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعاقبةِ منعِ الخير، والمبادرةُ ببذله."},"action":{"text":"تأمّل صدمتهم: فلمّا رأوها (الجنّةَ محترقةً سوداء) قالوا، من شدّةِ الصدمة ،: إنا لضالّون، أي أخطأنا طريقَ جنّتنا (ظنًّا أنها ليست جنّتهم)، أو: ضللنا عن الصوابِ فيما عزمنا عليه «فلما رأوها قالوا إنا لضالون»؛ ففي هذا بيانُ صدمتهم عند رؤيةِ عاقبةِ بخلهم، حتى ظنّوا أنهم أخطؤوا الطريق، ثم أدركوا أنه العقاب؛ فعاقبةُ منعِ الخيرِ الحرمانُ والصدمة؛ فاعتبر أنت بعاقبةِ من منع الخيرَ وبخل بحقِّ الله، قبل أن تُصدَم بها؛ فأصبح يقلّب كفّيه على ما أنفق فيها؛ يا حسرتى على ما فرّطت؛ فعاقبةُ منعِ الخيرِ والبخلِ الحرمانُ والندم؛ فاعتبر بها، وبادر ببذلِ الخيرِ وأداءِ الحقوق قبل فواتِ الأوان؛ فمن بذل الخيرَ نجا من الحرمان، ومن منعه صُدِم بالعاقبة؛ فاجعل الاعتبارَ بعاقبةِ منعِ الخيرِ والمبادرةَ ببذله دأبك."}},{"n":27,"reflection":{"text":"«بل نحن محرومون»: بل نحن محرومون من ثمرها وخيرها (بذنبنا)؛ ففي هذا اعترافهم بالحرمانِ بعد التبيّن؛ فاعلم أنّ منعَ الخيرِ يورث الحرمان، فمن منع الخيرَ حُرِمه، فابذل لتُرزَق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"بذلُ الخيرِ لنيلِ البركة، والحذرُ من الحرمانِ بالمنع."},"action":{"text":"تأمّل اعترافهم بالحرمان: بل نحن محرومون، أي بل حُرِمنا ثمرَ جنّتنا وخيرها بسببِ عزمنا على منعِ المساكين، فليست ضلالًا عن الطريقِ بل عقوبةٌ حُرِمنا بها «بل نحن محرومون»؛ ففي هذا اعترافهم بأنهم محرومون بذنبهم (منعِ الخيرِ والبخل)، بعد أن تبيّنوا أنها جنّتهم؛ فمنعُ الخيرِ يورث الحرمان؛ فاعلم أنت أنّ من منع الخيرَ والحقَّ حُرِم البركةَ والرزق؛ ما نقص مالٌ من صدقة؛ وما أنفقتم من شيءٍ فهو يُخلِفه؛ ومن يبخل فإنما يبخل عن نفسه؛ فمنعُ الخيرِ سبيلُ الحرمان، وبذلُه سبيلُ البركة؛ فابذل الخيرَ لتُرزَق وتُبارَك لك، ولا تمنعه فتُحرَم؛ فمن بذل الخيرَ بُورِك له، ومن منعه حُرِم؛ فاجعل بذلَ الخيرِ لنيلِ البركةِ والحذرَ من الحرمانِ بالمنعِ دأبك."}},{"n":28,"reflection":{"text":"«قال أوسطهم ألم أقل لكم لولا تسبحون»: قال أعدلهم وأفضلهم: ألم أقل لكم هلّا تُسبِّحون الله (وتستثنون وتشكرون)؟ ففي هذا بيانُ فضلِ من ذكّرهم بالحقّ؛ فكن ممّن يذكّر بالحقِّ وينهى عن المنكر، فالتذكيرُ بالحقِّ نجاة، فذكّر ونصح.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التذكيرُ بالحقِّ والنهيُ عن المنكر، والاعتبارُ بالناصح."},"action":{"text":"تأمّل قولَ الأوسط: قال أوسطهم، أي أعدلهم وأفضلهم رأيًا (الذي لم يوافقهم على البخل، أو وافق ثم ندم) ،: ألم أقل لكم لولا (هلّا) تُسبِّحون الله، أي تُنزِّهونه وتذكرونه وتستثنون في أيمانكم وتشكرون نعمته وتؤدّون حقَّه؟ فذكّرهم بما فرّطوا فيه «قال أوسطهم ألم أقل لكم لولا تسبحون»؛ ففي هذا بيانُ فضلِ من ذكّرهم بالحقِّ ونصحهم قبل وقوعِ العقوبة؛ فالناصحُ المذكِّرُ بالحقِّ محمود؛ فكن أنت ممّن يذكّر بالحقِّ وينهى عن المنكرِ وينصح، ولا تسكت على الباطل؛ ولتكن منكم أمّةٌ يدعون إلى الخير؛ وذكّر فإنّ الذكرى تنفع المؤمنين؛ فالتذكيرُ بالحقِّ والنهيُ عن المنكرِ من النجاة؛ فذكّر بالحقّ، وانهَ عن المنكر، وانصح، واعتبر بالناصحِ إذا نصحك؛ فمن ذكّر ونصح واعتبر أفلح، ومن سكت أو أعرض عن النصحِ خسر؛ فاجعل التذكيرَ بالحقِّ والنهيَ عن المنكرِ والاعتبارَ بالناصحِ دأبك."}},{"n":29,"reflection":{"text":"«قالوا سبحان ربنا إنا كنا ظالمين»: قالوا: سبحان ربّنا إنا كنّا ظالمين (لأنفسنا بالبخلِ ومنعِ الحقّ)؛ ففي هذا بيانُ توبتهم واعترافهم بالظلم؛ فبادر بالتوبةِ والاعترافِ بالذنبِ إذا أخطأت، فالاعترافُ بالظلمِ بابُ التوبة، فتب واعترف.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعترافُ بالظلمِ والتوبةُ منه، وتسبيحُ الله."},"action":{"text":"تأمّل توبتهم: قالوا (بعد أن ذكّرهم أوسطهم): سبحان ربّنا (تنزيهًا له وإقرارًا بأنه لم يظلمهم) إنا كنّا ظالمين، أي اعترفوا بأنهم ظلموا أنفسهم بالبخلِ ومنعِ حقِّ المساكين والعزمِ على ذلك «قالوا سبحان ربنا إنا كنا ظالمين»؛ ففي هذا بيانُ توبتهم ورجوعهم، واعترافهم بظلمهم لأنفسهم، وتسبيحهم لله؛ فالاعترافُ بالظلمِ بابُ التوبة؛ فبادر أنت بالاعترافِ بذنبك والتوبةِ منه إذا أخطأت، ونزّه الله وسبّحه؛ ربّنا ظلمنا أنفسنا وإن لم تغفر لنا وترحمنا لنكوننّ من الخاسرين؛ فسبّحان الله عمّا يصفون؛ لا إله إلا أنت سبحانك إني كنتُ من الظالمين؛ فالاعترافُ بالظلمِ وتسبيحُ الله من التوبة؛ فتب واعترف بذنبك، ونزّه الله، وأصلِح ما أفسدت؛ فمن اعترف بظلمه وتاب غُفِر له، ومن أصرّ خسر؛ فاجعل الاعترافَ بالظلمِ والتوبةَ منه وتسبيحَ الله دأبك."}},{"n":30,"reflection":{"text":"«فأقبل بعضهم على بعض يتلاومون»: فأقبل بعضهم على بعضٍ يلوم بعضهم بعضًا (على ما فعلوا)؛ ففي هذا بيانُ ندمهم وتلاومهم؛ فاحذر أن يقع بينك وبين شركائك في الإثمِ تلاومٌ يومَ الحساب، فالتلاومُ عاقبةُ الشراكةِ في الإثم، فاجتنب الإثم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ الشراكةِ في الإثم، والحذرُ من التلاومِ عليه."},"action":{"text":"تأمّل تلاومهم: فأقبل بعضهم على بعضٍ يتلاومون، أي يلوم بعضهم بعضًا على ما فعلوا من العزمِ على البخلِ ومنعِ المساكين، ويعتب بعضهم على بعض «فأقبل بعضهم على بعض يتلاومون»؛ ففي هذا بيانُ ندمهم وتلاومهم بعد وقوعِ العقوبة، حيث لم ينفعهم التلاوم؛ فالشراكةُ في الإثمِ عاقبتها التلاومُ والندم؛ فاحذر أنت الشراكةَ في الإثمِ والمعصية، لئلا يقع بينك وبين شركائك تلاومٌ يومَ الحساب؛ يتلاومون؛ وأقبل بعضهم على بعضٍ يتساءلون * قالوا إنكم كنتم تأتوننا عن اليمين؛ الأخلّاءُ يومئذٍ بعضهم لبعضٍ عدوٌّ إلا المتّقين؛ فالشراكةُ في الإثمِ تورث التلاومَ والعداوةَ يومَ القيامة؛ فاجتنب الإثمَ وشركاءه، وتعاون على البرِّ لا الإثم؛ فمن اجتنب الشراكةَ في الإثمِ سلم، ومن شارك فيه تلاوموا؛ فاجعل اجتنابَ الشراكةِ في الإثمِ والحذرَ من التلاومِ عليه دأبك."}},{"n":31,"reflection":{"text":"«قالوا يا ويلنا إنا كنا طاغين»: قالوا: يا هلاكنا إنا كنّا طاغين (متجاوزين الحدَّ في منعِ الحقّ)؛ ففي هذا بيانُ اعترافهم بالطغيان؛ فاحذر الطغيانَ ومجاوزةَ الحدّ، فالطغيانُ سبيلُ الهلاك، فالزم العدلَ والاعتدال.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الطغيانِ ومجاوزةِ الحدّ، ولزومُ الاعتدال."},"action":{"text":"تأمّل اعترافهم بالطغيان: قالوا: يا ويلنا (دعاءٌ على أنفسهم بالهلاكِ ندمًا) إنا كنّا طاغين، أي متجاوزين الحدَّ في البخلِ ومنعِ حقِّ المساكين والعزمِ على حرمانهم «قالوا يا ويلنا إنا كنا طاغين»؛ ففي هذا بيانُ اعترافهم بأنهم كانوا طاغين متجاوزين للحدِّ فيما عزموا عليه؛ فالطغيانُ (مجاوزةُ الحدِّ في المنعِ والظلم) سبيلُ الهلاك؛ فاحذر أنت الطغيانَ ومجاوزةَ الحدِّ في منعِ الحقوقِ والظلم، والزم العدلَ والاعتدال؛ اذهب إلى فرعونَ إنه طغى؛ فأمّا من طغى * وآثر الحياةَ الدنيا * فإنّ الجحيمَ هي المأوى؛ كلّا إنّ الإنسانَ ليطغى؛ فالطغيانُ ومجاوزةُ الحدِّ سبيلُ الهلاكِ والندم؛ فالزم العدلَ، ولا تتجاوز الحدَّ في المنعِ أو الظلم، وأدِّ الحقوق؛ فمن اعتدل والتزم الحدَّ نجا، ومن طغى هلك؛ فاجعل الحذرَ من الطغيانِ ومجاوزةِ الحدِّ ولزومَ الاعتدالِ دأبك."}},{"n":32,"reflection":{"text":"«عسى ربنا أن يبدلنا خيرا منها إنا إلى ربنا راغبون»: عسى ربّنا أن يُبدِلنا خيرًا منها، إنا إلى ربّنا راغبون؛ ففي هذا بيانُ رجوعهم إلى الله ورجائهم فيه؛ فارغب إلى الله عند المصيبةِ وارجُ خيره، فالرجوعُ إلى الله عند المصيبةِ توبةٌ ورجاء، فارغب إليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرغبةُ إلى الله والرجاءُ فيه عند المصيبة."},"action":{"text":"تأمّل رجوعهم ورجاءهم: عسى ربّنا أن يُبدِلنا خيرًا منها (من جنّتنا التي هلكت، جزاءَ توبتنا)؛ إنا إلى ربّنا راغبون، أي راجون عفوه وفضله، طالبون منه الخيرَ، تائبون إليه «عسى ربنا أن يبدلنا خيرا منها إنا إلى ربنا راغبون»؛ ففي هذا بيانُ رجوعهم إلى الله بعد المصيبة، ورجائهم أن يُبدِلهم خيرًا، ورغبتهم إليه؛ فالرجوعُ إلى الله عند المصيبةِ والرغبةُ إليه توبةٌ ورجاء؛ فارغب أنت إلى الله عند المصيبة، وارجُ خيره وفضله، وتب إليه؛ وإلى ربّك فارغب؛ فادعوه خوفًا وطمعًا؛ ونجّني برحمتك؛ فالرغبةُ إلى الله والرجاءُ فيه عند المصيبةِ سبيلُ الفرجِ والتبديلِ بالخير؛ فارغب إليه، وارجُ فضله، وتب، واطلب منه الخير؛ فمن رغب إلى الله ورجاه أُعطِي، ومن يئس أو أعرض حُرِم؛ فاجعل الرغبةَ إلى الله والرجاءَ فيه عند المصيبةِ دأبك."}},{"n":33,"reflection":{"text":"«كذلك العذاب ولعذاب الآخرة أكبر لو كانوا يعلمون»: مثلُ ذلك العذابِ (في الدنيا) يكون عذابُنا لمن خالف أمرنا، ولعذابُ الآخرةِ أكبرُ وأعظم، لو كانوا يعلمون؛ ففي هذا بيانُ أنّ عذابَ الدنيا أنموذجٌ، وأنّ عذابَ الآخرةِ أعظم؛ فاحذر عذابَ الآخرةِ الأكبر بالإيمانِ والعمل، فعذابُ الآخرةِ أكبر، فاعمل لتنجو منه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابِ الآخرةِ الأكبر، والعملُ للنجاةِ منه."},"action":{"text":"تأمّل أنّ عذابَ الآخرةِ أكبر: كذلك العذابُ، أي مثلُ عذابِ أصحابِ الجنّةِ في الدنيا (بزوالِ النعمة) يكون عذابُنا لمن خالف أمرنا وبخل بحقّنا؛ ولعذابُ الآخرةِ أكبرُ وأعظمُ وأدومُ من عذابِ الدنيا؛ لو كانوا يعلمون ذلك لارتدعوا «كذلك العذاب ولعذاب الآخرة أكبر لو كانوا يعلمون»؛ ففي هذا بيانُ أنّ عذابَ الدنيا (كإهلاكِ الجنّة) أنموذجٌ وتذكيرٌ، وأنّ عذابَ الآخرةِ أكبرُ وأعظم؛ فعذابُ الآخرةِ هو الأشدّ؛ فاحذر أنت عذابَ الآخرةِ الأكبرَ بالإيمانِ والعملِ الصالحِ وأداءِ الحقوق؛ ولعذابُ الآخرةِ أخزى وهم لا يُنصَرون؛ ولعذابُ الآخرةِ أشدُّ وأبقى؛ فعذابُ الدنيا يسيرٌ بجنبِ عذابِ الآخرةِ الأكبر؛ فاعمل للنجاةِ من عذابِ الآخرةِ بالإيمانِ والطاعةِ والتقوى؛ فمن عمل للنجاةِ نجا، ومن غفل وقع في العذابِ الأكبر؛ فاجعل الحذرَ من عذابِ الآخرةِ الأكبرِ والعملَ للنجاةِ منه دأبك."}}]},{"title":"جزاءُ المتّقين وإبطالُ دعاوى المجرمين","range":[34,41],"theme":"جزاءُ المتّقين «إن للمتقين عند ربهم جنات النعيم»، وإبطالِ التسويةِ بينهم وبين المجرمين «أفنجعل المسلمين كالمجرمين»، وسلسلةِ إبطالِ دعاوى المشركين بلا دليلٍ ولا كتابٍ ولا عهدٍ ولا كفيلٍ ولا شركاء «سلهم أيهم بذلك زعيم... فليأتوا بشركائهم إن كانوا صادقين»","verses":[{"n":34,"reflection":{"text":"«إن للمتقين عند ربهم جنات النعيم»: إنّ للمتّقين عند ربّهم جنّاتِ النعيم؛ ففي هذا بيانُ جزاءِ المتّقين؛ فاتّقِ الله لتنال جنّاتِ النعيم، فجنّاتُ النعيمِ للمتّقين، فاعمل بالتقوى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التقوى لنيلِ جنّاتِ النعيم."},"action":{"text":"تأمّل جزاءَ المتّقين: إنّ للمتّقين (الذين اتّقوا ربَّهم بامتثالِ أمره واجتنابِ نهيه) عند ربّهم جنّاتِ النعيمِ، أي بساتينَ ذاتِ نعيمٍ دائمٍ كامل «إن للمتقين عند ربهم جنات النعيم»؛ ففي هذا بيانُ جزاءِ المتّقين: جنّاتُ النعيمِ عند ربّهم، في مقابلِ عذابِ المكذّبين؛ فالجنّةُ جزاءُ التقوى؛ فاتّقِ أنت الله لتنال جنّاتِ النعيم؛ إنّ المتّقين في جنّاتٍ وعيون؛ إنّ المتّقين في مقامٍ أمين؛ إنّ للمتّقين مفازًا؛ فجنّاتُ النعيمِ معدّةٌ للمتّقين عند ربّهم؛ فاعمل بالتقوى (امتثالِ الأوامرِ واجتنابِ النواهي) لتفوز بها؛ فمن اتّقى نال جنّاتِ النعيم، ومن فرّط حُرِمها؛ فاجعل التقوى لنيلِ جنّاتِ النعيمِ دأبك."}},{"n":35,"reflection":{"text":"«أفنجعل المسلمين كالمجرمين»: أفنجعل المسلمين المطيعين كالمجرمين العاصين في الجزاء؟ ففي هذا إبطالُ التسويةِ بين المؤمنِ والمجرم؛ فاعلم أنّ الله لا يُسوّي بين المطيعِ والعاصي، فالعدلُ يقتضي التفريقَ بينهما، فاعمل لتكون من المسلمين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لتكون من المسلمين، واليقينُ بعدلِ الله في الجزاء."},"action":{"text":"تأمّل إبطالَ التسوية: أفنجعل المسلمين (المنقادين لله بالطاعةِ والإيمان) كالمجرمين (العاصين المكذّبين) في الجزاء؟ استفهامُ إنكارٍ، أي لا نُسوّي بينهما أبدًا، فهذا يُنافي الحكمةَ والعدل «أفنجعل المسلمين كالمجرمين»؛ ففي هذا إبطالُ التسويةِ بين المسلمِ والمجرمِ في الجزاء، وتقريرُ أنّ الله يميّز بينهما بعدله وحكمته؛ فلا يستوي المطيعُ والعاصي؛ فاعلم أنت أنّ الله لا يُسوّي بين المسلمِ والمجرم، فاعمل لتكون من المسلمين الفائزين؛ أم حسب الذين اجترحوا السيّئاتِ أن نجعلهم كالذين آمنوا وعملوا الصالحاتِ سواءً محياهم ومماتهم ساء ما يحكمون؛ أم نجعل المتّقين كالفجّار؛ لا يستوي أصحابُ النارِ وأصحابُ الجنّة؛ فالعدلُ يقتضي التفريقَ بين المسلمِ والمجرمِ في الجزاء؛ فاعمل بالإسلامِ والطاعةِ لتكون من المسلمين، وأيقن بعدلِ الله؛ فمن أسلم وأطاع فاز، ومن أجرم خسر؛ فاجعل العملَ لتكون من المسلمين واليقينَ بعدلِ الله في الجزاءِ دأبك."}},{"n":36,"reflection":{"text":"«ما لكم كيف تحكمون»: ما لكم، أيها المشركون، كيف تحكمون هذا الحكمَ الجائرَ (بالتسويةِ بين المطيعِ والعاصي، أو بأنّ لكم في الآخرةِ ما للمؤمنين)؟ ففي هذا إنكارٌ على حكمهم الفاسد؛ فاحذر الحكمَ بالباطلِ واتّبع حكمَ الله، فالحكمُ بغيرِ العدلِ فساد، فاتّبع حكمَ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ حكمِ الله العدل، والحذرُ من الحكمِ بالباطل."},"action":{"text":"تأمّل إنكارَ حكمهم: ما لكم، أيها المشركون، كيف تحكمون؟ استفهامُ إنكارٍ وتوبيخٍ على حكمهم الجائرِ الفاسد (حين زعموا أنهم إن بُعِثوا فلهم من الخيرِ مثلُ ما للمؤمنين، أو سوّوا بين المطيعِ والعاصي) «ما لكم كيف تحكمون»؛ ففي هذا إنكارٌ على المشركين في حكمهم الباطلِ الذي لا يستند إلى عقلٍ ولا نقل؛ فحكمهم فاسدٌ مخالفٌ للعدلِ والحكمة؛ فاحذر أنت الحكمَ بالباطلِ والهوى، واتّبع حكمَ الله العدل؛ أفحكمَ الجاهليّةِ يبغون ومن أحسنُ من الله حكمًا لقومٍ يوقنون؛ ومن لم يحكم بما أنزل الله فأولئك هم الظالمون؛ فالحكمُ بغيرِ العدلِ وحكمِ الله فسادٌ وجور؛ فاتّبع حكمَ الله، واحكم بالعدل، ولا تحكم بالهوى أو الباطل؛ فمن اتّبع حكمَ الله أصاب، ومن حكم بالباطلِ ضلّ؛ فاجعل اتّباعَ حكمِ الله العدلِ والحذرَ من الحكمِ بالباطلِ دأبك."}},{"n":37,"reflection":{"text":"«أم لكم كتاب فيه تدرسون»: أم لكم كتابٌ من الله تقرؤون فيه (ما يؤيّد دعواكم)؟ ففي هذا إبطالُ دعواهم بعدمِ الدليلِ النقلي؛ فلا تدّعِ في الدينِ ما لا دليلَ عليه، فالدعوى بلا دليلٍ باطلة، فاطلب الدليل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الدليلِ في الدين، والحذرُ من الدعوى بلا برهان."},"action":{"text":"تأمّل إبطالَ دعواهم بالنقل: أم لكم، أيها المشركون، كتابٌ من عند الله فيه تدرسون (تقرؤون وتتعلّمون) ما يؤيّد حكمكم الباطلَ (أنّ لكم عند الله ما للمؤمنين)؟ استفهامُ إنكارٍ، أي لا كتابَ لكم بذلك «أم لكم كتاب فيه تدرسون»؛ ففي هذا إبطالُ دعوى المشركين بعدمِ الدليلِ النقلي (الكتابِ المنزّل) على ما يزعمون؛ فدعواهم بلا كتابٍ ولا برهان؛ فلا تدّعِ أنت في الدينِ ما لا دليلَ عليه من كتابٍ أو سنّة؛ قل هاتوا برهانكم إن كنتم صادقين؛ أم أنزلنا عليهم سلطانًا فهو يتكلّم بما كانوا به يشركون؛ إن هي إلا أسماءٌ سمّيتموها؛ فالدعوى في الدينِ بلا دليلٍ من كتابٍ أو سنّةٍ باطلة؛ فاطلب الدليلَ فيما تعتقد وتقول، ولا تتّبع الظنَّ والهوى؛ فمن طلب الدليلَ واتّبعه أصاب، ومن ادّعى بلا برهانٍ ضلّ؛ فاجعل طلبَ الدليلِ في الدينِ والحذرَ من الدعوى بلا برهانٍ دأبك."}},{"n":38,"reflection":{"text":"«إن لكم فيه لما تخيرون»: إنّ لكم في ذلك الكتابِ لَما تختارون وتشتهون (لأنفسكم)؟ ففي هذا استهزاءٌ بدعواهم أنّ لهم ما يشتهون عند الله؛ فلا تبنِ آخرتك على الأماني، فالأمانيُّ لا تُغني، فاعمل ولا تتمنَّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للآخرةِ لا الاتّكالُ على الأماني."},"action":{"text":"تأمّل إبطالَ أمانيهم: إنّ لكم فيه (في ذلك الكتابِ المزعوم) لَما تخيّرون، أي لَما تختارونه وتشتهونه لأنفسكم من الخيرِ والكرامة؟ توبيخٌ لهم على بناءِ دعواهم على الأماني «إن لكم فيه لما تخيرون»؛ ففي هذا استهزاءٌ بدعواهم أنّ لهم عند الله ما يشتهون ويختارون، بلا دليلٍ ولا عمل؛ فالآخرةُ لا تُنال بالأماني بل بالعمل؛ فلا تبنِ أنت آخرتك على الأمانيِّ الباطلة، بل اعمل لها؛ ليس بأمانيّكم ولا أمانيِّ أهلِ الكتاب من يعمل سوءًا يُجزَ به؛ وقالوا لن يدخل الجنّةَ إلا من كان هودًا أو نصارى تلك أمانيّهم؛ أم يقولون نحن جميعٌ منتصر؛ فالأمانيُّ لا تُغني، والآخرةُ بالعمل؛ فاعمل للآخرةِ بالإيمانِ والطاعة، ولا تتّكل على الأماني؛ فمن عمل للآخرةِ نالها، ومن اتّكل على الأمانيِّ خسر؛ فاجعل العملَ للآخرةِ لا الاتّكالَ على الأمانيِّ دأبك."}},{"n":39,"reflection":{"text":"«أم لكم أيمان علينا بالغة إلى يوم القيامة إن لكم لما تحكمون»: أم لكم عهودٌ مؤكّدةٌ علينا باقيةٌ إلى يومِ القيامةِ بأنّ لكم ما تحكمون به لأنفسكم؟ ففي هذا إبطالُ دعواهم بعدمِ العهد؛ فلا تدّعِ على الله عهدًا لم يُعطِكه، فالدعوى على الله باطلة، فاصدق ولا تفترِ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الافتراءِ على الله، والصدقُ في الدعوى."},"action":{"text":"تأمّل إبطالَ دعوى العهد: أم لكم، أيها المشركون، أيمانٌ (عهودٌ ومواثيقُ مؤكّدةٌ) علينا بالغةٌ (مؤكّدةٌ متناهيةٌ في التوثيق) إلى يومِ القيامة، بأنّ لكم لَما تحكمون به لأنفسكم (من الكرامةِ والخير)؟ استفهامُ إنكارٍ، أي لا عهدَ لكم بذلك «أم لكم أيمان علينا بالغة إلى يوم القيامة إن لكم لما تحكمون»؛ ففي هذا إبطالُ دعوى المشركين أنّ لهم على الله عهدًا مؤكّدًا بأن يُعطيهم ما يحكمون؛ فلا عهدَ لهم؛ فلا تدّعِ أنت على الله عهدًا لم يُعطِكه، ولا تفترِ عليه؛ أم اتّخذتم عند الله عهدًا فلن يُخلِف الله عهده أم تقولون على الله ما لا تعلمون؛ أطّلع الغيبَ أم اتّخذ عند الرحمن عهدًا؛ فالدعوى على الله بعهدٍ لم يكن افتراءٌ وكذب؛ فاصدق، ولا تفترِ على الله، ولا تدّعِ ما ليس لك؛ فمن صدق ولم يفترِ نجا، ومن افترى على الله خسر؛ فاجعل الحذرَ من الافتراءِ على الله والصدقَ في الدعوى دأبك."}},{"n":40,"reflection":{"text":"«سلهم أيهم بذلك زعيم»: سلهم، يا محمد، أيّهم بذلك الحكمِ (الذي يحكمونه لأنفسهم) كفيلٌ ضامن؟ ففي هذا تحدٍّ لهم بإقامةِ الكفيلِ على دعواهم؛ فلا تلتزم ما لا تقدر عليه ولا تدّعِ ما لا برهانَ له، فالدعوى تحتاج برهانًا، فاطلبه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ ادّعاءِ ما لا برهانَ له، وطلبُ الحجّة."},"action":{"text":"تأمّل التحدّي بالكفيل: سلهم، يا محمد، أيّهم بذلك (الحكمِ الذي يحكمونه لأنفسهم من الكرامةِ عند الله) زعيمٌ، أي كفيلٌ ضامنٌ يقوم به ويؤكّده؟ تحدٍّ لهم أن يأتوا بمن يكفل صحّةَ دعواهم «سلهم أيهم بذلك زعيم»؛ ففي هذا تحدٍّ للمشركين بأن يقيموا كفيلًا أو حجّةً على دعواهم الباطلة، وإظهارُ عجزهم؛ فدعواهم بلا كفيلٍ ولا برهان؛ فلا تدّعِ أنت ما لا برهانَ له، ولا تلتزم ما لا تقدر على إثباته؛ قل هاتوا برهانكم؛ أم لهم شركاءُ فليأتوا بشركائهم إن كانوا صادقين؛ فالدعوى تحتاج برهانًا وكفيلًا؛ فلا تدّعِ ما لا حجّةَ له، واطلب البرهانَ فيما تعتقد؛ فمن أقام الحجّةَ على قوله صدق، ومن ادّعى بلا برهانٍ عجز؛ فاجعل عدمَ ادّعاءِ ما لا برهانَ له وطلبَ الحجّةِ دأبك."}},{"n":41,"reflection":{"text":"«أم لهم شركاء فليأتوا بشركائهم إن كانوا صادقين»: أم لهم شركاءُ (آلهةٌ أو أعوانٌ) يضمنون لهم ما يدّعون؟ فليأتوا بشركائهم إن كانوا صادقين؛ ففي هذا تحدٍّ لهم بإحضارِ شركائهم، وإبطالُ الشرك؛ فلا شريكَ لله يضمن أو ينفع، فالشركاءُ عاجزون، فأخلِص لله وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ العبادةِ لله وحده، وإبطالُ الشرك."},"action":{"text":"تأمّل تحدّيَ الشركاء: أم لهم شركاءُ، أي آلهةٌ أو أعوانٌ يضمنون لهم ما يحكمون به لأنفسهم من الكرامة؟ فليأتوا بشركائهم (يُحضِروهم ليشهدوا أو يشفعوا) إن كانوا صادقين في دعواهم «أم لهم شركاء فليأتوا بشركائهم إن كانوا صادقين»؛ ففي هذا تحدٍّ للمشركين بإحضارِ شركائهم المزعومين ليؤيّدوا دعواهم، وإظهارُ عجزِ الشركاءِ وبطلانِ الشرك؛ فلا شريكَ لله يضمن أو ينفع؛ فأخلِص أنت العبادةَ لله وحده، ولا تُشرِك به شيئًا؛ قل ادعوا شركاءكم ثم كيدون فلا تُنظِرون؛ أروني ماذا خلقوا من الأرض؛ هل من شركائكم من يفعل من ذلكم من شيء؛ فالشركاءُ عاجزون لا يملكون نفعًا ولا شفاعة، والشركُ باطل؛ فأخلِص لله وحده، وابطل الشركَ من قلبك وعملك؛ فمن أخلص لله أفلح، ومن أشرك خسر؛ فاجعل إخلاصَ العبادةِ لله وحده وإبطالَ الشركِ دأبك."}}]},{"title":"يومُ يُكشَف عن ساقٍ والاستدراجُ والأمرُ بالصبر","range":[42,52],"theme":"مشهدُ **«يوم يكشف عن ساق ويدعون إلى السجود فلا يستطيعون»** وذلّةِ الكفّارِ لإبائهم السجودَ حالَ سلامتهم، وتهديدِ المكذّبين بالاستدراجِ والإملاء «إن كيدي متين»، ونفيِ سؤالِ الأجرِ وعلمِ الغيبِ عنهم، والأمرِ **«فاصبر لحكم ربك ولا تكن كصاحب الحوت»** وتداركِ يونسَ بالنعمةِ واجتبائه، وشدّةِ حسدِ الكفّارِ «ليزلقونك بأبصارهم»، وختمِ السورةِ **«وما هو إلا ذكر للعالمين»**","verses":[{"n":42,"reflection":{"text":"«يوم يكشف عن ساق ويدعون إلى السجود فلا يستطيعون»: يومَ يُكشَف عن ساقٍ (أي عن شدّةٍ وهولٍ عظيم، ويكشف الربُّ عن ساقه كما يليق به) ويُدعَون إلى السجودِ فلا يستطيعون (المنافقون والكفّار)؛ ففي هذا بيانُ هولِ يومِ القيامةِ وحرمانِ الكفّارِ من السجود؛ فاسجد لله في الدنيا لتُوفَّق للسجودِ في الآخرة، فالسجودُ في الدنيا سبيلُ التوفيقِ له في الآخرة، فأكثِر السجود.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإكثارُ من السجودِ في الدنيا، والاستعدادُ لهولِ القيامة."},"action":{"text":"تأمّل هولَ يومِ القيامة: يومَ يُكشَف عن ساقٍ، أي يومَ القيامةِ حين يشتدّ الأمرُ ويعظم الهول (والعربُ تقول: كشفت الحربُ عن ساقٍ عند اشتدادها)، وقد ثبت في الصحيح أنّ الربَّ يكشف عن ساقه كما يليق بجلاله فيسجد له المؤمنون؛ ويُدعَى الكفّارُ والمنافقون إلى السجودِ فلا يستطيعون (تعود ظهورهم طبقًا واحدًا لا يسجدون، عقوبةً لهم على تركهم السجودَ في الدنيا) «يوم يكشف عن ساق ويدعون إلى السجود فلا يستطيعون»؛ ففي هذا بيانُ هولِ يومِ القيامة، وأنّ المنافقين والكفّارَ يُحرَمون السجودَ يومئذٍ جزاءَ إعراضهم عنه في الدنيا؛ فمن سجد لله في الدنيا وُفِّق له في الآخرة؛ فأكثِر أنت من السجودِ لله في الدنيا (في الصلاةِ خاصّة) لتُوفَّق له يومَ القيامة؛ فيكشف عن ساقٍ فيسجد كلُّ مؤمنٍ ومؤمنة، ويبقى من كان يسجد رياءً وسمعةً فيذهب ليسجد فيعود ظهره طبقًا واحدًا؛ واسجد واقترب؛ فالسجودُ في الدنيا سبيلُ التوفيقِ له في الآخرةِ والنجاةِ من هولها؛ فأكثِر السجودَ لله، وأخلِصه، واستعدّ لهولِ القيامة؛ فمن سجد لله مخلصًا وُفِّق ونجا، ومن أعرض حُرِم وخُذِل؛ فاجعل الإكثارَ من السجودِ في الدنيا والاستعدادَ لهولِ القيامةِ دأبك."}},{"n":43,"reflection":{"text":"«خاشعة أبصارهم ترهقهم ذلة وقد كانوا يدعون إلى السجود وهم سالمون»: ذليلةً أبصارهم تغشاهم ذلّةٌ، وقد كانوا يُدعَون إلى السجودِ في الدنيا وهم أصحّاءُ قادرون فأبوا؛ ففي هذا بيانُ ذلّةِ الكفّارِ يومَ القيامةِ جزاءَ إبائهم السجود؛ فبادر بالسجودِ والطاعةِ وأنت قادر، فالتفريطُ حالَ القدرةِ يورث الذلّ، فاغتنم قدرتك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اغتنامُ القدرةِ للطاعةِ والسجود، والحذرُ من التفريط."},"action":{"text":"تأمّل ذلّةَ الكفّار: خاشعةً (ذليلةً منكسرةً) أبصارهم؛ ترهقهم (تغشاهم وتعلوهم) ذلّةٌ وحسرة؛ وقد كانوا يُدعَون إلى السجودِ (بالأذانِ والإقامةِ ودعوةِ الرسل) في الدنيا وهم سالمون (أصحّاءُ قادرون على السجود) فأبوا واستكبروا «خاشعة أبصارهم ترهقهم ذلة وقد كانوا يدعون إلى السجود وهم سالمون»؛ ففي هذا بيانُ ذلّةِ الكفّارِ والمنافقين يومَ القيامة، وأنّ حرمانهم السجودَ يومئذٍ جزاءُ إبائهم عنه في الدنيا حالَ قدرتهم وسلامتهم؛ فالتفريطُ حالَ القدرةِ يورث الذلَّ والحرمان؛ فبادر أنت بالسجودِ والطاعةِ وأنت قادرٌ سالم، قبل أن تُحرَمها؛ وامتازوا اليومَ أيها المجرمون؛ ترهقهم ذلّة؛ وقد كانوا يُدعَون إلى السجودِ وهم سالمون فأبوا؛ فالتفريطُ في الطاعةِ حالَ القدرةِ يورث الذلَّ والحرمانَ يومَ القيامة؛ فاغتنم صحّتك وقدرتك للطاعةِ والسجود، ولا تُفرِّط؛ فمن اغتنم قدرته للطاعةِ نجا، ومن فرّط حالَ القدرةِ ذلّ؛ فاجعل اغتنامَ القدرةِ للطاعةِ والسجودِ والحذرَ من التفريطِ دأبك."}},{"n":44,"reflection":{"text":"«فذرني ومن يكذب بهذا الحديث سنستدرجهم من حيث لا يعلمون»: فدعني، يا محمد، ومن يكذّب بهذا القرآن، سنستدرجهم (نأخذهم بالنعمِ قليلًا قليلًا) من حيث لا يعلمون؛ ففي هذا تهديدٌ للمكذّبين بالاستدراج؛ فاحذر أن تكون النعمُ استدراجًا مع الإصرارِ على المعصية، فالاستدراجُ بالنعمِ عقوبةٌ خفيّة، فراقب حالك مع الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاستدراجِ بالنعم، ومراقبةُ الحالِ مع الله."},"action":{"text":"تأمّل تهديدَ الاستدراج: فذرني، يا محمد، ومن يكذّب بهذا الحديثِ (القرآن)، أي كِلْ أمرهم إليّ فأنا أكفيكهم؛ سنستدرجهم، أي نأخذهم بالعقوبةِ قليلًا قليلًا، ونمدّهم بالنعمِ والصحّةِ كلّما أحدثوا ذنبًا، فيظنّونها كرامةً وهي عقوبة، من حيث لا يعلمون (لا يشعرون أنه استدراج) «فذرني ومن يكذب بهذا الحديث سنستدرجهم من حيث لا يعلمون»؛ ففي هذا تهديدٌ للمكذّبين بالقرآنِ بالاستدراجِ (إمهالهم بالنعمِ ليزدادوا إثمًا ثم يأخذهم بغتة)؛ فالنعمُ مع الإصرارِ على المعصيةِ قد تكون استدراجًا؛ فاحذر أنت أن تكون النعمُ التي تُقبِل عليك مع إصرارك على المعصيةِ استدراجًا؛ سنستدرجهم من حيث لا يعلمون؛ فلمّا نسوا ما ذُكِّروا به فتحنا عليهم أبوابَ كلِّ شيء حتى إذا فرحوا بما أوتوا أخذناهم بغتة؛ إنما نملي لهم ليزدادوا إثمًا؛ فالاستدراجُ بالنعمِ عقوبةٌ خفيّةٌ للمُصِرّ على المعصية؛ فراقب حالك مع الله، وإذا رأيت النعمَ مع المعصيةِ فاحذر، وتب؛ فمن راقب حاله وتاب نجا، ومن اغترّ بالنعمِ مع المعصيةِ استُدرِج؛ فاجعل الحذرَ من الاستدراجِ بالنعمِ ومراقبةَ الحالِ مع الله دأبك."}},{"n":45,"reflection":{"text":"«وأملي لهم إن كيدي متين»، وأُمهِلهم (أُطيل لهم في الإمهال)، إنّ كيدي متينٌ (قويٌّ شديد)؛ ففي هذا بيانُ إمهالِ الله للكفّارِ وشدّةِ أخذه؛ فلا تغترّ بإمهالِ الله فإنّ أخذه شديد، فالإمهالُ ليس إهمالًا، فبادر بالتوبة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بإمهالِ الله، والمبادرةُ بالتوبة."},"action":{"text":"تأمّل إمهالَ الله وشدّةَ أخذه: وأُملي لهم، أي أُمهِلهم وأُطيل لهم المدّةَ في النعمةِ والإمهال (ليزدادوا إثمًا)؛ إنّ كيدي متينٌ، أي أخذي وتدبيري لهم قويٌّ شديدٌ لا يُفلِتون منه «وأملي لهم إن كيدي متين»؛ ففي هذا بيانُ أنّ الله يُمهِل الكفّارَ ويُملي لهم، لكنّ أخذه إذا أخذ شديدٌ متين؛ فالإمهالُ ليس إهمالًا؛ فلا تغترّ أنت بإمهالِ الله لك أو للعصاة، فإنّ أخذه شديد؛ ولا يحسبنّ الذين كفروا أنما نملي لهم خيرٌ لأنفسهم إنما نملي لهم ليزدادوا إثمًا؛ وكذلك أخذُ ربّك إذا أخذ القرى وهي ظالمةٌ إنّ أخذه أليمٌ شديد؛ فأمليتُ للذين كفروا ثم أخذتهم فكيف كان نكير؛ فإمهالُ الله ابتلاءٌ لا إهمال، وأخذه شديدٌ متين؛ فلا تغترّ بالإمهال، وبادر بالتوبةِ قبل الأخذ؛ فمن بادر بالتوبةِ نجا، ومن اغترّ بالإمهالِ أُخِذ بغتة؛ فاجعل عدمَ الاغترارِ بإمهالِ الله والمبادرةَ بالتوبةِ دأبك."}},{"n":46,"reflection":{"text":"«أم تسألهم أجرا فهم من مغرم مثقلون»: أم تسألهم، يا محمد، على تبليغِ الرسالةِ أجرًا فهم مثقلون بالغرامة؟ ففي هذا نفيُ العذرِ عن إعراضهم، فما سألهم أجرًا؛ فاعلم أنّ الحقَّ يُبلَّغ بلا مقابل، فالدعوةُ لله لا للأجرِ الدنيوي، فادعُ محتسبًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الدعوةُ لله محتسبًا بلا مقابل، ونفيُ العذرِ عن المعرضين."},"action":{"text":"تأمّل نفيَ سؤالِ الأجر: أم تسألهم، يا محمد، أجرًا (أجرةً على تبليغِ الرسالة) فهم من مغرمٍ (غرامةٍ وخسارة) مثقلون (فيثقل عليهم اتّباعك)؟ استفهامُ إنكارٍ، أي لا تسألهم أجرًا، فما لهم عذرٌ في الإعراض «أم تسألهم أجرا فهم من مغرم مثقلون»؛ ففي هذا نفيُ أن يكون النبيُّ ﷺ يسأل قومه أجرًا على الدعوة، فيَثقل عليهم؛ فما لهم عذرٌ في إعراضهم، إذ الحقُّ يُبلَّغ بلا مقابل؛ فالدعوةُ إلى الله لله لا للأجرِ الدنيوي؛ فادعُ أنت إلى الله محتسبًا بلا مقابلٍ دنيويّ؛ قل ما أسألكم عليه من أجرٍ إلا من شاء أن يتّخذ إلى ربّه سبيلًا؛ وما أسألكم عليه من أجرٍ إن أجري إلا على ربِّ العالمين؛ اتّبعوا من لا يسألكم أجرًا وهم مهتدون؛ فالرسلُ والدعاةُ يبلّغون الحقَّ لله لا للأجرِ الدنيوي؛ فادعُ إلى الله محتسبًا، وبلّغ الحقَّ بلا مقابل؛ فمن دعا لله محتسبًا أُجِر، ومن دعا للدنيا حُرِم؛ فاجعل الدعوةَ لله محتسبًا بلا مقابلٍ ونفيَ العذرِ عن المعرضين دأبك."}},{"n":47,"reflection":{"text":"«أم عندهم الغيب فهم يكتبون»: أم عندهم علمُ الغيبِ فهم يكتبون منه ما يحكمون به؟ ففي هذا نفيُ أن يكون عندهم علمُ الغيب؛ فلا تحكم في الغيبِ بلا علم، فعلمُ الغيبِ عند الله وحده، فقل الحقَّ عن علم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ القولِ في الغيبِ بلا علم، والاعترافُ بأنّ الغيبَ لله."},"action":{"text":"تأمّل نفيَ علمِ الغيب: أم عندهم الغيبُ، أي أعندهم علمُ الغيبِ (اللوحُ المحفوظُ أو ما غاب) فهم يكتبون منه ما يشاؤون ويحكمون به لأنفسهم من الكرامة؟ استفهامُ إنكارٍ، أي ليس عندهم علمُ الغيب «أم عندهم الغيب فهم يكتبون»؛ ففي هذا نفيُ أن يكون عند المشركين علمُ الغيبِ الذي يبنون عليه دعواهم؛ فلا يعلمون الغيبَ ولا يكتبون منه؛ فلا تحكم أنت في الغيبِ (كمصيرِ الناسِ في الآخرة، أو ما سيكون) بلا علمٍ من الله؛ قل لا يعلم من في السماواتِ والأرضِ الغيبَ إلا الله؛ عالمُ الغيبِ فلا يُظهِر على غيبه أحدًا؛ وعنده مفاتحُ الغيبِ لا يعلمها إلا هو؛ فعلمُ الغيبِ عند الله وحده، لا يعلمه المشركون ولا غيرهم؛ فلا تقل في الغيبِ بلا علم، واعترف بأنّ الغيبَ لله، وقل الحقَّ عن علم؛ فمن وقف عند علمه ولم يقل في الغيبِ بلا علمٍ سلم، ومن تكلّف الغيبَ ضلّ؛ فاجعل تركَ القولِ في الغيبِ بلا علمٍ والاعترافَ بأنّ الغيبَ لله دأبك."}},{"n":48,"reflection":{"text":"«فاصبر لحكم ربك ولا تكن كصاحب الحوت إذ نادى وهو مكظوم»: فاصبر، يا محمد، لحكمِ ربّك (وقضائه في إمهالِ المكذّبين)، ولا تكن كصاحبِ الحوتِ (يونسَ) إذ نادى ربَّه وهو مملوءٌ غيظًا وكربًا؛ ففي هذا الأمرُ بالصبرِ والنهيُ عن العجلةِ كيونس؛ فاصبر لحكمِ الله ولا تعجل، فالصبرُ على حكمِ الله سبيلُ الفرج، فاصبر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ لحكمِ الله، والحذرُ من العجلةِ والضجر."},"action":{"text":"تأمّل الأمرَ بالصبر: فاصبر، يا محمد، لحكمِ ربّك (لقضائه وقدره، ولإمهاله المكذّبين، ولأذاهم) صبرًا جميلًا؛ ولا تكن كصاحبِ الحوتِ (يونسَ عليه السلام) إذ نادى ربَّه (في بطنِ الحوت: لا إله إلا أنت سبحانك إني كنتُ من الظالمين) وهو مكظومٌ، أي مملوءٌ غمًّا وكربًا وغيظًا، حين ذهب مغاضبًا لقومه قبل أن يُؤذَن له فالتقمه الحوت «فاصبر لحكم ربك ولا تكن كصاحب الحوت إذ نادى وهو مكظوم»؛ ففي هذا الأمرُ للنبيِّ ﷺ بالصبرِ لحكمِ ربّه، والنهيُ عن العجلةِ والضجرِ كما وقع من يونسَ حين عجل ولم يصبر؛ فالصبرُ على حكمِ الله سبيلُ الفرج؛ فاصبر أنت لحكمِ الله وقضائه، ولا تعجل، ولا تضجر من أذى الحقّ؛ واصبر لحكمِ ربّك فإنك بأعيننا؛ فاصبر كما صبر أولو العزمِ من الرسل ولا تستعجل لهم؛ وذا النونِ إذ ذهب مغاضبًا؛ فالصبرُ على حكمِ الله وعدمُ العجلةِ سبيلُ الفرجِ والتوفيق؛ فاصبر لحكمِ الله، ولا تعجل، ولا تضجر؛ فمن صبر لحكمِ الله فُرِّج عنه، ومن عجل وضجر ندم؛ فاجعل الصبرَ لحكمِ الله والحذرَ من العجلةِ والضجرِ دأبك."}},{"n":49,"reflection":{"text":"«لولا أن تداركه نعمة من ربه لنبذ بالعراء وهو مذموم»: لولا أن أدركته رحمةٌ من ربّه لأُلقِيَ بالأرضِ الخاليةِ مذمومًا (لكنّ الله تداركه بتوبته)؛ ففي هذا بيانُ فضلِ الله على يونسَ بالنعمةِ والتوبة؛ فاطلب رحمةَ الله بالتوبةِ والذكرِ عند الشدّة، فرحمةُ الله تُنجِّي، فتب واذكر الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ رحمةِ الله بالتوبةِ والذكرِ عند الشدّة."},"action":{"text":"تأمّل تداركَ النعمة: لولا أن تداركه (أدركته وأنقذته) نعمةٌ (رحمةٌ) من ربّه، أي بتوفيقه للتوبةِ والتسبيحِ في بطنِ الحوت وقبولها منه، لَنُبِذ (لأُلقِي من بطنِ الحوت) بالعراءِ (الأرضِ الخاليةِ) وهو مذمومٌ (ملومٌ على تقصيره)؛ لكنّ الله تداركه برحمته فنُبِذ غيرَ مذموم «لولا أن تداركه نعمة من ربه لنبذ بالعراء وهو مذموم»؛ ففي هذا بيانُ فضلِ الله على يونسَ حيث تداركه برحمته وقبِل توبته فنجا؛ فرحمةُ الله والتوبةُ تُنجِّيان من الشدائد؛ فاطلب أنت رحمةَ الله بالتوبةِ والتسبيحِ والذكرِ عند الشدّة؛ فنادى في الظلماتِ أن لا إله إلا أنت سبحانك إني كنتُ من الظالمين * فاستجبنا له ونجّيناه من الغمّ وكذلك نُنجِّي المؤمنين؛ فلولا أنه كان من المسبّحين للبث في بطنه إلى يومِ يُبعَثون؛ فرحمةُ الله والتوبةُ والتسبيحُ تُنجِّي من الكروب؛ فتب واذكر الله وسبّحه عند الشدّة، واطلب رحمته؛ فمن تاب وذكر الله ورجا رحمته نجا، ومن قنط هلك؛ فاجعل طلبَ رحمةِ الله بالتوبةِ والذكرِ عند الشدّةِ دأبك."}},{"n":50,"reflection":{"text":"«فاجتباه ربه فجعله من الصالحين»: فاختاره ربّه واصطفاه، فجعله من الصالحين؛ ففي هذا بيانُ ثمرةِ التوبةِ: الاجتباءُ والصلاح؛ فتب إلى الله يجتبِك ويجعلك من الصالحين، فالتوبةُ سبيلُ الاجتباءِ والصلاح، فتب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التوبةُ سبيلُ الاجتباءِ والصلاح."},"action":{"text":"تأمّل ثمرةَ التوبة: فاجتباه ربُّه، أي اصطفاه واختاره وقرّبه بعد توبته؛ فجعله من الصالحين (الكاملين في الصلاحِ والعمل) «فاجتباه ربه فجعله من الصالحين»؛ ففي هذا بيانُ ثمرةِ توبةِ يونسَ ورجوعه: أنّ الله اجتباه وجعله من الصالحين، فردّه إلى مكانته بل أعلى؛ فالتوبةُ الصادقةُ سبيلُ الاجتباءِ والصلاح؛ فتب أنت إلى الله توبةً صادقة، يجتبِك ويقرّبك ويجعلك من الصالحين؛ ثم اجتباه ربّه فتاب عليه وهدى (في آدم)؛ إنّ الله يحبّ التوّابين؛ وألحقني بالصالحين؛ فالتوبةُ ترفع صاحبها وتجعله من الصالحين المجتبَين؛ فتب إلى الله، وأصلِح عملك، واطلب أن تكون من الصالحين؛ فمن تاب واجتُبِي صار من الصالحين، ومن أصرّ حُرِم؛ فاجعل التوبةَ سبيلَ الاجتباءِ والصلاحِ دأبك."}},{"n":51,"reflection":{"text":"«وإن يكاد الذين كفروا ليزلقونك بأبصارهم لما سمعوا الذكر ويقولون إنه لمجنون»، وإن يكاد الذين كفروا لَيُزلِقونك بأبصارهم (يصيبونك بالعينِ من شدّةِ حسدهم وبغضهم) لمّا سمعوا القرآن، ويقولون: إنه لمجنون؛ ففي هذا بيانُ شدّةِ عداوةِ الكفّارِ وحسدهم للنبيِّ ﷺ؛ فاحتمِ بالله من حسدِ الحاسدين وعداوةِ المعادين، فالله يحفظ أولياءه، فاعتصم به.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاحتماءُ بالله من الحسدِ والعداوة، والثباتُ على الحق."},"action":{"text":"تأمّل عداوةَ الكفّارِ وحسدهم: وإن يكاد الذين كفروا لَيُزلِقونك بأبصارهم، أي يكادون يصيبونك بالعينِ (بأبصارهم النافذةِ من شدّةِ الحسدِ والبغض)، أو يكادون يُزيلونك عن مكانك من شدّةِ نظرهم إليك بالعداوة، لمّا سمعوا الذكرَ (القرآن)؛ ويقولون (بغيًا وعنادًا): إنه لمجنون «وإن يكاد الذين كفروا ليزلقونك بأبصارهم لما سمعوا الذكر ويقولون إنه لمجنون»؛ ففي هذا بيانُ شدّةِ عداوةِ الكفّارِ وحسدهم للنبيِّ ﷺ، حتى كادوا يصيبونه بالعين، ورميهم له بالجنون؛ وفيه إثباتُ إصابةِ العين؛ فالحسدُ والعداوةُ سلاحُ أعداءِ الحق؛ فاحتمِ أنت بالله من حسدِ الحاسدين وعينهم وعداوةِ المعادين؛ ومن شرِّ حاسدٍ إذا حسد؛ وددنا كثيرٌ من أهلِ الكتابِ لو يردّونكم؛ قل أعوذ بربِّ الفلق؛ فالله يحفظ أولياءه من كيدِ الأعداءِ وحسدهم؛ فاعتصم بالله، وتحصّن بالأذكار، واثبت على الحقّ، ولا يهزّك حسدهم وطعنهم؛ فمن احتمى بالله حُفِظ، ومن غفل تضرّر؛ فاجعل الاحتماءَ بالله من الحسدِ والعداوةِ والثباتَ على الحقِّ دأبك."}},{"n":52,"reflection":{"text":"«وما هو إلا ذكر للعالمين»، وما القرآنُ إلا ذكرٌ وعظةٌ وشرفٌ للعالمين (الجنِّ والإنس)؛ ففي هذا تقريرُ أنّ القرآنَ ذكرٌ للعالمين لا قولُ مجنون؛ فاجعل القرآنَ ذكرك وعظتك وشرفك، فالقرآنُ ذكرٌ للعالمين، فتذكّر به واعمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"جعلُ القرآنِ ذكرًا وعظةً وشرفًا، والعملُ به."},"action":{"text":"تأمّل أنّ القرآنَ ذكرٌ للعالمين: وما هو (القرآنُ الذي رموا صاحبه بالجنونِ لأجله) إلا ذكرٌ للعالمين، أي عظةٌ وتذكيرٌ وشرفٌ وهدايةٌ لجميعِ العالمين (الجنِّ والإنس)، لا قولُ مجنونٍ كما يزعمون «وما هو إلا ذكر للعالمين»؛ ففي هذا (وهو ختامُ السورة) تقريرُ أنّ القرآنَ ذكرٌ وعظةٌ وشرفٌ للعالمين كافّة، وردٌّ على من رماه بالجنون؛ فالقرآنُ ذكرٌ وهدايةٌ للعالمين؛ فاجعل أنت القرآنَ ذكرك وموعظتك وشرفك، وتذكّر به، واعمل بما فيه؛ إن هو إلا ذكرٌ وقرآنٌ مبين؛ وإنه لذكرٌ لك ولقومك؛ لقد أنزلنا إليكم كتابًا فيه ذكركم؛ ونزّلنا عليك الكتابَ تبيانًا لكلِّ شيء؛ فالقرآنُ ذكرٌ للعالمين، وشرفٌ لمن تمسّك به، وهدايةٌ لمن اتّبعه؛ فاجعله ذكرك وعظتك وشرفك، وتدبّره، واعمل به، وادعُ إليه؛ فمن جعل القرآنَ ذكره وعمل به اهتدى وشرُف، ومن أعرض عنه ضلّ؛ فاجعل جعلَ القرآنِ ذكرًا وعظةً وشرفًا والعملَ به دأبك."}}]}],"coverage":{"covered":52,"total":52}};
